      // the not-yet hint instead of framing someone else's session page.\n        // Exact hits are trusted unconditionally; legacy responses (field\n        // absent) behave exactly as before.\n        const sessionOurs =\n            hostSessionId === undefined ||\n            status === undefined ||\n            status.viaFallback !== true ||\n            status.conversationId === hostSessionId;\n        // #4281: framed ⇒ fill the whole conversation view (full-height\n        // column, no outer padding, borderless frame on flex:1, slim top\n        // action row); every hint state keeps its own breathing room.\n        const framed = origin !== undefined && liveEmbed === \"ok\" && sessionId !== null && sessionOurs;\n        const hintP = (key: string): unknown => createElement(\"p\", { style: { margin: 0, opacity: 0.7, lineHeight: 1.6 } }, t(key));\n        // #3693: kick off a clipboard write of the readout line; the label\n        // flips to \"copied\" briefly on success.\n        const startCopy = (target: string): void => {\n            void copyText(target).then((ok) => {\n                if (!ok) return;\n                setCopied(true);\n                setTimeout(() => setCopied(false), 2000);\n            });\n        };\n        const errorBox = (error: string | undefined): unknown =>\n            error === undefined\n                ? null\n                : renderProbeError(t, error, copied, () => startCopy(error));\n        let middle: unknown;\n        if (origin === undefined) {\n            middle = hintP(\"degraded\");\n        } else if (remoteBlocked) {\n            middle = renderRemoteBlock(t, origin, errorBox(liveEmbedError));\n        } else if (liveEmbed === \"stale\") {\n            // Frozen proxy predates the ?embed=1 route: framing is impossible\n            // on any page, including the session one.\n            middle = hintP(\"stale\");\n        } else if (framed) {\n            middle = createElement(\n                \"iframe\",\n                {\n                    src: `${origin}/__bili/?embed=1&lang=${lang}${theme !== undefined ? `&theme=${theme}` : \"\"}#/session/${encodeURIComponent(sessionId)}`,\n                    title: t(\"title\"),\n                    style: {\n                        display: \"block\",\n                        flex: 1,\n                        width: \"100%\",\n                        height: \"100%\",\n                        minHeight: 0,\n                        border: \"none\",\n                        background: \"transparent\",\n                    },\n                },\n            );\n        } else if (status?.ok === true && status.phase === \"pre-first-request\") {\n            // No session row exists yet: waiting is truthful, framing impossible.\n            middle = hintP(\"ctx_waiting\");\n        } else if (status === undefined) {\n            middle = hintColumn(hintP(fetchFailed ? \"degraded\" : \"connecting\"), errorBox(fetchFailed ? statusError : undefined));\n        } else if (!status.ok) {\n            middle = hintP(\"ctx_nodata\");\n        } else {\n            // Session resolved but the embed verdict has not landed yet (first\n            // probe tick) — or a status build that answers without a session id:\n            // honest connecting / not-yet hints instead of an empty frame.\n            // chain-advisory lands here with liveEmbed \"ok\" ⇒ ctx_nodata, and\n            // must NEVER read as a stale-build claim. #3693: if the embed\n            // probe itself is failing, its raw error rides beneath the hint.\n            middle = hintColumn(hintP(liveEmbed === \"ok\" ? \"ctx_nodata\" : \"connecting\"), errorBox(liveEmbedError));\n        }\n        return createElement(\n            \"div\",\n            { ref: surfaceRef, style: { display: \"flex\", flexDirection: \"column\", height: \"100%\", minWidth: 0, minHeight: 0 } },\n            origin !== undefined\n                ? createElement(\n                    \"div\",\n                    { style: { display: \"flex\", alignItems: \"center\", gap: 8, flexShrink: 0, padding: \"8px 12px\" } },\n                    createElement(\n                        \"button\",\n                        {\n                            type: \"button\",\n                            onClick: () => setReloadTick((x) => x + 1),\n                            style: { cursor: \"pointer\", borderRadius: 8, border: \"1px solid rgba(127,127,127,0.4)\", background: \"transparent\", color: \"inherit\", fontFamily: \"inherit\", fontSize: 13, lineHeight: \"20px\", padding: \"4px 14px\" },\n                        },\n                        t(\"ctx_refresh\"),\n                    ),\n                    openWebButton(origin, t, { fontSize: \"13\", lineHeight: \"20px\", padding: \"4px 14px\" }),\n                )\n                : null,\n            createElement(\n                \"div\",\n                { style: framed ? { display: \"flex\", flex: 1, minHeight: 0 } : { flex: 1, minHeight: 0, padding: 16 } },\n                middle,\n            ),\n        );\n    };\n    const panel = (titled: boolean): ((props: Record<string, unknown>) => unknown) => () => {\n        const [origin, setOrigin] = useState<string | undefined>(readOrigin());\n        const [page, setPage] = useState<PageId>(\"overview\");\n        // #2559: synchronous first paint — the very first render already pins\n        // the palette to the host's current ground (no wrong-scheme flash).\n        const [theme, setTheme] = useState<(\"light\" | \"dark\") | undefined>(detectHostTheme);\n        // #3100: embed pre-flight verdict for the CURRENT origin — a verdict\n        // recorded for a previous origin (mid-session re-bind) is stale by\n        // definition and reads as \"pending\" until its own probe lands.\n        const [embed, setEmbed] = useState<EmbedState | undefined>(() => {\n            const o = readOrigin();\n            const v = o !== undefined ? embedVerdicts.get(o) : undefined;\n            return o !== undefined && v !== undefined ? { origin: o, verdict: v } : undefined;\n        });\n        // #3693: copy feedback for the probe-error readout — declared\n        // unconditionally so hook order stays stable across renders.\n        const [copied, setCopied] = useState(false);\n        // #2288: no guard on the snapshot — the live route is authoritative\n        // for the whole mount, so a stale boot value is corrected in place.\n        // #3100: each resolution also probes the new origin's embed route in\n        // flight, and every tick re-drives pending origins (snapshot-only\n        // hosts never resolve through this path again after mount).\n        useEffect(\n            () =>\n                probeOrigin(\n                    (o) => {\n                        setOrigin(o);\n                        probeEmbedRoute(o, setEmbed);\n                    },\n                    setTheme,\n                    (o) => probeEmbedRoute(o, setEmbed),\n                ),\n            [],\n        );\n        // #3100: mount-time probe for a snapshot origin and re-probe on any\n        // origin change (covers hosts whose live route never answers).\n        useEffect(() => {\n            if (origin !== undefined) probeEmbedRoute(origin, setEmbed);\n        }, [origin]);\n        const liveEmbed: EmbedVerdict | undefined = embed !== undefined && embed.origin === origin ? embed.verdict : undefined;\n        // #3693: the live probe's last network failure (transient — retried\n        // every poll tick until a verdict lands).\n        const liveEmbedError: string | undefined = embed !== undefined && embed.origin === origin ? embed.error : undefined;\n        // #3816: remote page + loopback origin ⇒ unreachable by construction —\n        // explain the fix instead of spinning on \"connecting…\". ANY resolved\n        // verdict outranks the mismatch: a verdict means THIS browser actually\n        // reached the origin (same-machine access through a LAN IP still\n        // reaches the loopback) — never shadow a working frame or the stale\n        // notice of a reachable-but-frozen proxy.\n        const remoteBlocked = remoteMismatch(origin) && liveEmbed === undefined;\n        const lang = t(\"nav\") === zhDict.nav ? \"zh\" : \"en\";\n        // #3693: kick off a clipboard write of the readout line; the label\n        // flips to \"copied\" briefly on success.\n        const startCopy = (target: string): void => {\n            void copyText(target).then((ok) => {\n                if (!ok) return;\n                setCopied(true);\n                setTimeout(() => setCopied(false), 2000);\n            });\n        };\n        const errorBox = (error: string | undefined): unknown =>\n            error === undefined\n                ? null\n                : renderProbeError(t, error, copied, () => startCopy(error));\n        let middle: unknown;\n        if (origin === undefined) {\n            middle = createElement(\"p\", { style: { margin: 0, opacity: 0.7, lineHeight: 1.6 } }, t(\"degraded\"));\n        } else if (remoteBlocked && origin !== undefined) {\n            // The jump button targets the panel's config page (#/config) in a\n            // fresh tab. For a purely remote browser that address is still\n            // unreachable — the file-edit text above is the primary route;\n            // the button serves same-LAN/tunneled access where it lands on\n            // the exact field to set. #3693: the raw probe failure proving\n            // the unreachability rides underneath, copyable for reports.\n            middle = renderRemoteBlock(t, origin, errorBox(liveEmbedError));\n        } else if (liveEmbed === \"stale\") {\n            middle = createElement(\"p\", { style: { margin: 0, opacity: 0.7, lineHeight: 1.6 } }, t(\"stale\"));\n        } else if (liveEmbed === \"ok\") {\n            middle = createElement(\n                \"div\",\n                { style: { display: \"flex\", flexDirection: \"column\", gap: 10 } },\n                createElement(\n                    \"div\",\n                    { style: { display: \"flex\", gap: 8, flexWrap: \"wrap\", alignItems: \"center\" } },\n                    PAGE_IDS.map((id) =>\n                        createElement(\n                            \"button\",\n                            {\n                                key: id,\n                                type: \"button\",\n                                onClick: () => setPage(id),\n                                style: {\n                                    cursor: \"pointer\",\n                                    borderRadius: 8,\n                                    border: id === page ? \"1px solid rgba(127,127,127,0.7)\" : \"1px solid rgba(127,127,127,0.4)\",\n                                    background: id === page ? \"rgba(127,127,127,0.12)\" : \"transparent\",\n                                    color: \"inherit\",\n                                    fontFamily: \"inherit\",\n                                    fontSize: 13,\n                                    fontWeight: id === page ? 600 : 400,\n                                    lineHeight: \"20px\",\n                                    padding: \"4px 14px\",\n                                },\n                            },\n                            t(PAGE_KEYS[id]),\n                        ),\n                    ),\n                    // The open-in-browser action rides the TAB row — right\n                    // after the logs tab, pushed to the row's far end —\n                    // instead of sitting in the footer below the iframe.\n                    openWebButton(origin, t, { marginLeft: \"auto\", fontSize: \"13\", lineHeight: \"20px\", padding: \"4px 14px\" }),\n                ),\n                createElement(\"iframe\", {\n                    src: `${origin}/__bili/?embed=1&lang=${lang}${theme ? `&theme=${theme}` : \"\"}#/${page}`,\n                    title: t(\"title\"),\n                    style: {\n                        display: \"block\",\n                        width: \"100%\",\n                        height: EMBED_HEIGHT,\n                        border: \"1px solid rgba(127,127,127,0.4)\",\n                        borderRadius: 8,\n                        background: \"transparent\",\n                    },\n                }),\n            );\n        } else {\n            // #3693: \"connecting…\" alone hid every failure — when the probe is\n            // actually failing, its raw error rides beneath the hint.\n            middle = hintColumn(\n                createElement(\"p\", { style: { margin: 0, opacity: 0.7, lineHeight: 1.6 } }, t(\"connecting\")),\n                errorBox(liveEmbedError),\n            );\n        }\n        return createElement(\n            \"div\",\n            { style: { display: \"flex\", flexDirection: \"column\", gap: 12, padding: \"20px 8px\" } },\n            titled ? createElement(\"h3\", { style: { margin: 0, fontSize: 16, fontWeight: 600 } }, t(\"title\")) : null,\n            middle,\n            createElement(\n                \"div\",\n                { style: { display: \"flex\", alignItems: \"center\", gap: 10, flexWrap: \"wrap\" } },\n                createElement(\"p\", { style: { margin: 0, opacity: 0.7, fontSize: 13, lineHeight: 1.6, flex: 1, minWidth: 200 } }, t(\"hint\")),\n                // ok 状态:按钮在上方页签行(日志页签后面);degraded/stale\n                // 仍留在页脚作后备入口(#2448 同一按钮)。#3816: remoteBlocked\n                // 时按钮指向的正是那个够不到的回环地址——死链,一并隐藏。\n                liveEmbed === \"ok\" || remoteBlocked ? null : openWebButton(origin, t),\n            ),\n        );\n    };\n    // #4254 defect ②: frame-level upstream-unavailable pill (shell.overlay slot).\n    // Polls the loopback-gated GET /__bili/upstreams read surface (#4257) and\n    // renders one row per unreachable upstream; returns null while every upstream\n    // is reachable, so the banner auto-dismisses when circuits close + alerts clear.\n    // Purely additive UI — no request path changes. Display identity is the\n    // forwarded host:port (bili is a transparent pipe); provider/model reverse\n    // lookup stays host-side.\n    const upstreamBanner = (): ((props?: Record<string, unknown>) => unknown) => () => {\n        const [origin, setOrigin] = useState<string | undefined>(readOrigin());\n        const [rows, setRows] = useState<UpstreamRow[]>([]);\n        useEffect(() => probeOrigin((o) => setOrigin(o)), []);\n        useEffect(() => {\n            if (origin === undefined) return;\n            let cancelled = false;\n            const load = (): void => {\n                void fetch(`${origin}/__bili/upstreams`)\n                    .then((res) => res.json() as Promise<unknown>)\n                    .then((raw) => { if (!cancelled) setRows(parseUpstreamHealth(raw)); })\n                    .catch(() => { if (!cancelled) setRows([]); });\n            };\n            load();\n            const timer: ReturnType<typeof setInterval> = setInterval(load, UPSTREAM_POLL_MS);\n            return () => { cancelled = true; clearInterval(timer); };\n        }, [origin]);\n        if (rows.length === 0) return null;\n        const header = rows.length === 1 ? t(\"upstreams_down_one\") : t(\"upstreams_down_many\").replace(\"{n}\", String(rows.length));\n        return createElement(\n            \"div\",\n            { role: \"status\", style: { display: \"flex\", flexDirection: \"column\", gap: 4, maxWidth: 520, padding: \"8px 12px\", borderRadius: 8, border: \"1px solid rgba(217,63,11,0.5)\", background: \"rgba(217,63,11,0.1)\" } },\n            createElement(\"div\", { style: { fontSize: 13, fontWeight: 600 } }, header),\n            ...rows.map((r) => {\n                const code = r.code !== undefined ? ` ${r.code}` : \"\";\n                // #6026: 0 means fail-fast already lifted (probe-eligible, and probes are\n                // request-driven — bili never auto-retries), so a countdown would be a lie.\n                const s = r.nextProbeInMs !== undefined && r.nextProbeInMs > 0 ? Math.ceil(r.nextProbeInMs / 1000) : undefined;\n                const eta = s !== undefined ? ` · ${t(\"upstream_retry_hint\").replace(\"{s}\", String(s))}` : \"\";\n                return createElement(\"div\", { key: r.host, style: { fontFamily: \"ui-monospace, SFMono-Regular, Menlo, monospace\", fontSize: 12, lineHeight: 1.5 } }, `${r.host} · ${r.kind}${code} ×${r.count}${eta}`);\n            }),\n        );\n    };\n    ctx.slots.inject(\n        \"settings.section\",\n        () => ctx.slots.register({ name: \"settings.section\", id: \"bili\", order: 100, label: () => t(\"nav\"), locale: NS }, panel(true)),\n    );\n    ctx.slots.inject(\n        \"plugins.bundle.config\",\n        () => ctx.slots.register({ name: \"plugins.bundle.config\", key: \"billion-context\", locale: NS }, panel(false)),\n    );\n    // #3862: session Context tab. order 30 sits right of the built-in chat (0)\n    // and trajectory (10) tabs and right of dsh-context's Context tab (20)\n    // when both are installed. Deferred injection is fail-open on hosts whose\n    // build lacks the slot. #4237: dsh.contextTab=false (web settings / config\n    // file / BILI_DSH_CONTEXT_TAB=0) skips this slot entirely — hiding removes\n    // only the top-bar entry; the ledger stays reachable through the settings\n    // section, the plugin bundle config face, the Web UI and /acp. A custom\n    // label (dsh.contextTabLabel) replaces the built-in name where another\n    // plugin occupies it.\n    const ctxGate = readCtxTabFace();\n    if (!ctxGate.hidden) {\n        ctx.slots.inject(\n            \"conversation.view\",\n            () => ctx.slots.register({ name: \"conversation.view\", id: \"bili-context\", order: 30, label: () => ctxGate.label ?? t(\"tab_ctx\"), locale: NS }, contextPanel()),\n        );\n    }\n    // #4254 defect ②: frame-level upstream-unavailable pill. Deferred injection\n    // is fail-open on hosts whose build lacks the shell.overlay slot (same\n    // discipline as the session Context tab above).\n    ctx.slots.inject(\n        \"shell.overlay\",\n        () => ctx.slots.register({ name: \"shell.overlay\", id: \"bili-upstreams\", order: 100, label: () => t(\"upstreams_label\"), locale: NS }, upstreamBanner()),\n    );\n}\n"
    },
    {
      "path": "src/plugin.ts",
      "content": "import { ACP_RETIRE_TOOL_NAME, ACP_RESTORE_TOOL_NAME, ACP_REWRITE_TOOL_NAME, BLOCKED_REF, BLOCK_OP_TOOL_NAMES, COMPRESS_TOOL_NAME, type CompressionCore, type Config, type CoreMessage, type NudgeDecision, type RetrievalExport, type ToolPrompts, applyAcpToolOverrides, applyRetrieve, countMessageTokens, parseStoredPlaceholder, prune } from \"acp-kernel\";\nimport { imageRescaleEnabled, publicSnapshotCapBytes } from \"./knobs.js\";\nimport { buildStatusPanel } from \"acp-kernel/panel\";\nimport { fileURLToPath } from \"node:url\";\nimport type { ServerResponse } from \"node:http\";\nimport fs from \"node:fs\";\nimport path from \"node:path\";\nimport { createHash } from \"node:crypto\";\nimport { CORRUPT_SIBLING_CAP, getStore, pruneCorruptSiblings, storageStatusLabel, kvStore } from \"./persist.js\";\nimport { cloneStoreForRefs } from \"./store.js\";\nimport { acquireInFlight, createSession, getSessionAsync, publishForkSession, diagnoseSuccessWithoutUsage, effectiveConfig, findSessionByCanonicalId, listSessions, markCompactionBoundary, markDirty, noteAbortedTurn, noteTruncatedUpstream, peekSession, releaseInFlight, releaseNudgeHold, statusInputBaseline, withSessionLock, type Session } from \"./session.js\";\nimport { clientConversationHeader } from \"./session-id.js\";\nimport { buildContextView } from \"./context-view.js\";\nimport { ABSORB_TOOL_NAME, BILI_ACP_TOOLS_ANTHROPIC, BILI_ACP_TOOLS_ANTHROPIC_NO_RANGE, BILI_ACP_TOOLS_OPENAI, BILI_ACP_TOOLS_OPENAI_NO_RANGE, BILI_ACP_TOOLS_RESPONSES_NO_RANGE, PROXY_TOOL_NAMES, READ_ORIGINAL_IMAGE_TOOL, READ_ORIGINAL_IMAGE_TOOL_NAME, READ_ORIGINAL_IMAGE_TOOL_OPENAI, READ_ORIGINAL_IMAGE_TOOL_RESPONSES, RETRIEVE_TOOL_NAME, RULE_TOOL, RULE_TOOL_NAME, RULE_TOOL_OPENAI, RULE_TOOL_RESPONSES, SEARCH_CONTEXT_TOOL_NAME, absorbToolsFor, blockOpsTools, retrieveToolsFor, withAcpNotes, withAcpNotesOpenAI } from \"./compress-tool.js\";\nimport { blockOpsEnabled, effectiveBlockOpsConfig } from \"./acp-block-ops.js\";\nimport { externalSummaryEnabled, externalSummaryMaxToolDurationMs, withExternalSummaryTools } from \"./external-summary-surface.js\";\nimport { salvageCompressArgs } from \"./plugin-compress-salvage.js\";\nimport { absorbEnabled, effectiveAbsorbConfig, isProxyToolFor } from \"./absorb.js\";\nimport { effectiveRulesEnabled, rulesEnabled } from \"./rules-feature.js\";\nimport { executeProxyToolAsync } from \"./loop/core.js\";\nimport type { ProxyToolResult } from \"./proxy-tool-result.js\";\nimport { normalizeSseLineEndings, finalizeSseLineEndings } from \"./sse-util.js\";\nimport { composeStreamFilters, containsBiliInternalText, containsEchoResidue, containsMarkerLineText, containsRenderTagText, containsToolCallEmissionText, containsToolCallXmlFragment, createBiliArtifactFilter, createIdentityStreamFilter, createMarkerLineFilter, createTagEchoFilter, isOrphanMarkupText, mayStartBiliInternal, mayStartDegenerateRenderTag, mayStartMarkerLine, mayStartRenderTag, mayStartToolCallEmission, stripAcpTags, stripAnthropicText, stripOpenaiChatText, stripResponsesText, type TagEchoFilter } from \"./loop/tag-echo-filter.js\";\nimport { log as loggerLog } from \"./logger.js\";\nimport { scanModelOutputForPhantomAttachments } from \"./phantom-attachment.js\";\nimport { ccrEnabled, ccrLoopConfig, contentStoreOf, retrieveToolName } from \"./store.js\";\nimport { formatProtectedMass, uncoveredAudit, type ProtectedMassLedger } from \"./uncovered.js\";\nimport { emitStreamError, emitUpstreamTruncation } from \"./stream-error.js\";\nimport type { TruncationDiag } from \"./stream-error.js\";\nimport { recordAttributionReport } from \"./server/attribution-status.js\";\nimport type { HandoffReply } from \"./server/handoff-response.js\";\nimport { captureHandoffJson, HANDOFF_REPLY_MAX_BYTES } from \"./server/handoff-response.js\";\n\n/** #2328 Q2: what the pipes know about the upstream HTTP response whose body\n *  they are piping — threaded in by server.ts so the truncation diag can cite\n *  status/content-type without the pipes holding the Response object. */\nexport interface UpstreamMeta {\n    status?: number;\n    contentType?: string;\n    requestId?: string;\n    opencodeLogId?: string;\n    cfRay?: string;\n}\n\n/** #2328 Q4: does the dangling partial event left at a cut carry the opening\n *  bytes of the wire's own terminal? Factual byte evidence only — this never\n *  guesses about frames that parsed but were classified otherwise. */\nfunction tailLooksTerminal(tail: string, protocol: WireProtocol | \"responses\"): boolean {\n    // [DONE] torn anywhere past `data: [DO` is still recognizable as the\n    // terminal byte arriving.\n    if (/^data: \\[DO/.test(tail)) return true;\n    if (protocol === \"anthropic\") return /event: message_stop/.test(tail.slice(0, 64)) || /\"type\"\\s*:\\s*\"message_stop\"/.test(tail);\n    if (protocol === \"openai\") {\n        // `\"finish_reason\":null` rides EVERY chat chunk — only a quoted\n        // (non-null) value counts, which is the final chunk's signature.\n        return /\"finish_reason\"\\s*:\\s*\"/.test(tail);\n    }\n    if (protocol === \"google\") {\n        // finishReason only ever appears on Gemini's terminal chunk.\n        return /\"finishReason\"\\s*:\\s*\"/.test(tail);\n    }\n    // responses: the completion-family event is the terminal.\n    return /event: response\\.(?:completed|failed|incomplete)/.test(tail.slice(0, 64)) ||\n        /\"type\"\\s*:\\s*\"response\\.(?:completed|failed|incomplete)\"/.test(tail);\n}\nimport { degenerateTurnWarning, endsWithAnnouncement, endsWithDraftClose, requestExpectsProseSummary } from \"./degenerate-turn.js\";\nimport { getChangelog, latestChangelog, warmChangelogOnce } from \"./web/changelog.js\";\nimport { warmBlogRefreshOnce } from \"./web/blog-refresh.js\";\nimport { PANEL_BOX_FOOTER } from \"./acp-panel.js\";\nimport { excludeDeadRefRanges } from \"./acp-status.js\";\nimport { describeAdvisory, getAdvisoryState } from \"./advisory.js\";\nimport { describeUpdateReady, getUpdateVisibility } from \"./update-notes.js\";\nimport { warnCacheCollapse } from \"./cache-warn.js\";\nimport { currentContextObservation, recordContextObservation, settleUsageReport } from \"./cache-ledger.js\";\nimport { billOutputUsage } from \"./billing.js\";\nimport { promptInputTotal, declaredInclusiveFromUsage, type WireProtocol } from \"./util.js\";\nimport { stateDir } from \"./paths.js\";\nimport { lookupToolUseIdSession, lookupToolWitness, recordToolUseId, recordToolWitness } from \"./tool-ring.js\";\nimport { awaitDrain } from \"./server/stream-io.js\";\nimport { incomingCoreMessages, seedTimestampsFromParent } from \"./fork-adoption.js\";\nimport { BUILD_COMMIT } from \"./version.js\";\nimport { isExternalSummaryBlock } from \"./external-summary-marker.js\";\n\n// The proxy's own version, read from package.json at runtime (works in both dev\n// via tsx and bundled via tsup). Shown in the /acp panel header, aligned with\n// billion-context-pi's `billion-context-pi@<version>` format.\nconst PROXY_VERSION = (() => {\n    try {\n        const here = fileURLToPath(import.meta.url);\n        const pkg = path.join(path.dirname(here), \"..\", \"package.json\");\n        return (JSON.parse(fs.readFileSync(pkg, \"utf8\")).version as string) ?? \"dev\";\n    } catch {\n        return \"dev\";\n    }\n})();\n\n// Cooperative plugin protocol (\"内外呼应\", issue #1): an agent-side plugin\n// registers the ACP tools NATIVELY with its agent and runs the agent's own\n// tool loop, while the proxy stays the single compression authority (state,\n// history folding, philosophy prompt, nudges). The plugin:\n//   1. GETs /__bili/plugin/manifest and registers the served tool schemas\n//      natively (single source of truth — zero schema drift between proxy\n//      and plugin),\n//   2. sends x-bili-plugin: <agent> + x-bili-plugin-conversation: <id> on\n//      every model request. The proxy then suppresses wire-level tool\n//      injection for that session (tools are native) and stops intercepting\n//      proxy-named tool calls — the model's compress call flows back to the\n//      agent untouched, the plugin forwards it to (3),\n//   3. executes tools via POST /__bili/plugin/tool {conversationId, tool,\n//      args}, under the session lock, against the same executeProxyTool the\n//      wire-mode compress loop uses.\n\nconst PLUGIN_AGENT_HEADER = \"x-bili-plugin\";\nconst PLUGIN_CONVERSATION_HEADER = \"x-bili-plugin-conversation\";\n/** #920: legacy-lane marker. Set by the absorbed opencode-acp wrapper for\n *  sessions that still run through the legacy DCP machinery — the proxy\n *  forwards such requests VERBATIM (no wire injection, no session binding,\n *  no compress loop): the legacy extension owns compression for them. */\nconst PLUGIN_BYPASS_HEADER = \"x-bili-plugin-bypass\";\nconst PLUGIN_CONTEXT_WINDOW_HEADER = \"x-bili-plugin-context-window\";\nconst PLUGIN_MAX_OUTPUT_HEADER = \"x-bili-plugin-max-output\";\nconst PLUGIN_MODEL_HEADER = \"x-bili-plugin-model\";\n/** #4855: per-request compression-channel override, only honored from an announced plugin\n *  (same gate as window/model above). A host that registers the ACP tools natively but keeps them\n *  OUT of the outgoing request — Hermes defers every plugin toolset behind tool_search — still\n *  needs its identity and budget bound to the plugin conversation. Stamping \"proxy\" says exactly\n *  that: keep the plugin identity, but serve compression through the proxy's wire channel (inject\n *  the tools, execute compress server-side) instead of suppressing injection for a caller that\n *  cannot run the tools. Without it the request falls back to anonymous proxy mode (pfa-* fork id,\n *  default window, no /acp binding), which is the defect it exists for. */\nconst PLUGIN_COMPRESSION_HEADER = \"x-bili-plugin-compression\";\n/** #1102/#1106: stamped \"1\" by plugins whose host mints one conversation id per\n *  persona (opencode: subagents get their own child session ids). Since the\n *  instructions fingerprint became an allowlist (#1106 — exempt is the\n *  default for every non-codex/non-claude signal), this declaration is\n *  vestigial: hosts keep stamping it for protocol compatibility with older\n *  proxies, but current proxies key verbatim regardless. */\nconst PLUGIN_INSTRUCTIONS_MUTABLE_HEADER = \"x-bili-plugin-instructions-mutable\";\n/** #1699: the host's per-request persona/agent id (opencode v2 stamps its own\n *  taxonomy — \"title\", \"build\", \"plan\", ...). Carries INTENT the request body\n *  cannot express: opencode v2 title-gen requests carry NO max_tokens (options\n *  {} for kind===\"title\"), so the output-budget side-request heuristic (#388)\n *  can never see them — they were misclassified as main turns and got the full\n *  compress prompt + tool injected into the title model. Known side-request\n *  agents route by intent (side-request.ts SIDE_REQUEST_AGENTS); explicit \"main\"\n *  vetoes side heuristics, while other persona ids remain inert telemetry. */\nconst PLUGIN_REQUEST_AGENT_HEADER = \"x-bili-plugin-agent\";\n/** #6880: the host's declared PURPOSE for the dispatch (dsh stamps\n *  GenerateOptions.purpose verbatim — \"session-title\", \"compaction\",\n *  \"auto-review\", \"timeline-report\", ...; its contract: ordinary\n *  conversation requests leave it unset). Carries the side/main intent\n *  that content-guessing used to approximate: a PLUGIN-ANNOUNCED request\n *  with a non-empty purpose is a side request by declaration, no per-feature\n *  template matching needed (the content recognizers stay as the fallback\n *  for pre-#6880 plugin installs). Honored only behind the x-bili-plugin\n *  marker, same trust discipline as the conversation header: an unannounced\n *  client's purpose header is inert telemetry. */\nconst PLUGIN_PURPOSE_HEADER = \"x-bili-plugin-purpose\";\n/** #6880 v2 wire: the post-#6883 dsh plugin stamps this sentinel for MAIN\n *  turns (dsh leaves GenerateOptions.purpose unset for ordinary conversation,\n *  so no real dsh purpose can collide with it). PRESENCE of the header in any\n *  value is the declaration that this conversation's plugin announces every\n *  dispatch's purpose — main traffic then keys the raw session id directly\n *  (dsh mints one UUID per session, ids never recycle) instead of routing\n *  through the persona-order ladder, and its auxiliary traffic is a declared\n *  side request by the header alone. The sentinel itself is NOT a side:\n *  handle.ts normalizes it back to \"absent\" before the side classification. */\nexport const PLUGIN_PURPOSE_CONVERSATION = \"conversation\";\n\nconst PLUGIN_PROTOCOL_VERSION = 1;\n\n/** #1567: legacy callers without a native tool-call id get a synthetic id.\n *  Their resent compress pair is recognized by range as a summary carrier. */\nconst PLUGIN_FOLD_CALLID_PREFIX = \"plugin_\";\nexport function isPluginFoldCallId(callId: string | undefined): boolean {\n    return typeof callId === \"string\" && callId.startsWith(PLUGIN_FOLD_CALLID_PREFIX);\n}\n\n/** Reconnect legacy plugin blocks before the kernel mistakes their live carriers for orphans. */\nexport function reconcilePluginFoldCallIds(session: Session, messages: CoreMessage[]): number {\n    const blocks = new Map<string, typeof session.state.blocks>();\n    for (const block of session.state.blocks) {\n        if (!block.active || !block.startRef || !block.endRef) continue;\n        const key = JSON.stringify([block.startRef, block.endRef]);\n        const sameRange = blocks.get(key) ?? [];\n        sameRange.push(block);\n        blocks.set(key, sameRange);\n    }\n    const calls = new Map<string, Set<string>>();\n    const results = new Map(messages.filter((m) => m.contentType === \"tool-result\" && m.toolCallId).map((m) => [m.toolCallId!, m.text ?? \"\"]));\n    for (const message of messages) {\n        if (message.contentType !== \"tool-call\" || message.toolName !== \"compress\" || !message.toolCallId) continue;\n        try {\n            const args = JSON.parse(message.text ?? \"\") as { content?: unknown; startId?: unknown; endId?: unknown };\n            for (const range of Array.isArray(args?.content) ? args.content : [args]) {\n                if (!range || typeof range.startId !== \"string\" || typeof range.endId !== \"string\") continue;\n                const key = JSON.stringify([range.startId, range.endId]);\n                if (!blocks.has(key)) continue;\n                const ids = calls.get(key) ?? new Set<string>();\n                ids.add(message.toolCallId);\n                calls.set(key, ids);\n            }\n        } catch { /* Invalid historical arguments cannot establish ownership. */ }\n    }\n    let changed = 0;\n    for (const [key, sameRange] of blocks) {\n        const block = sameRange[0]!;\n        const ids = calls.get(key);\n        if (sameRange.length !== 1 || !isPluginFoldCallId(block.compressCallId) || ids?.size !== 1) continue;\n        const id = ids.values().next().value!;\n        const receipt = results.get(id);\n        if (!receipt?.startsWith(\"[Compressed \") || !receipt.split(\"\\n\").some((line) => line.startsWith(` · ${block.blockId} full summary `))) continue;\n        block.compressCallId = id;\n        changed++;\n    }\n    if (changed > 0) markDirty(session);\n    return changed;\n}\n\nconst VERSION = (() => {\n    try {\n        const here = fileURLToPath(import.meta.url);\n        const pkg = path.join(path.dirname(here), \"..\", \"package.json\");\n        return (JSON.parse(fs.readFileSync(pkg, \"utf8\")).version as string) ?? \"dev\";\n    } catch {\n        return \"dev\";\n    }\n})();\n\nfunction headerValue(headers: Record<string, string | string[] | undefined>, name: string): string | undefined {\n    const v = headers[name];\n    const s = typeof v === \"string\" ? v : Array.isArray(v) ? v[0] : undefined;\n    const t = s?.trim();\n    return t && t.length > 0 ? t : undefined;\n}\n\nexport function pluginPurposeHeader(headers: Record<string, string | string[] | undefined>): string | undefined {\n    // #6880: purpose is a protocol-internal steering signal — honoring it\n    // without the plugin announcement would let any client that can reach\n    // the endpoint opt its traffic out of the session pipeline. A real\n    // plugin sends the marker and the purpose together.\n    return pluginAgentHeader(headers) !== undefined ? headerValue(headers, PLUGIN_PURPOSE_HEADER) : undefined;\n}\n\nexport function pluginAgentHeader(headers: Record<string, string | string[] | undefined>): string | undefined {\n    return headerValue(headers, PLUGIN_AGENT_HEADER);\n}\n\nexport function pluginConversationHeader(headers: Record<string, string | string[] | undefined>): string | undefined {\n    return headerValue(headers, PLUGIN_CONVERSATION_HEADER);\n}\n\n/** The plugin reports its agent's own model context window (what the agent\n *  configured, e.g. a pinned/overridden contextWindow). It replaces the\n *  native-window source (built-in table / models.dev registry) in the config\n *  cascade — operator tuning (compress.modelContextLimit) still outranks it. */\nfunction pluginContextWindowHeader(headers: Record<string, string | string[] | undefined>): number | undefined {\n    const raw = headerValue(headers, PLUGIN_CONTEXT_WINDOW_HEADER);\n    if (raw === undefined) return undefined;\n    const n = Number.parseInt(raw, 10);\n    return Number.isFinite(n) && n > 0 ? n : undefined;\n}\n\n/** The reported window is honored ONLY from a request that also announces\n *  itself as a plugin (x-bili-plugin). This header is protocol-internal:\n *  honoring it from a plain (non-plugin) client would let anyone who can\n *  reach the endpoint rewrite the nudge denominator. A real plugin sends\n *  both headers together (see the manifest's `headers` block). */\nexport function pluginReportedContextWindow(headers: Record<string, string | string[] | undefined>): number | undefined {\n    return pluginAgentHeader(headers) !== undefined ? pluginContextWindowHeader(headers) : undefined;\n}\n\n/** Configured max output tokens (runtime-info protocol #955). Same gate as\n *  the window header: a plain client must not be able to move the proxy's\n *  output-headroom reservation by name. Used only when the request body\n *  carries no max_tokens of its own — the wire value always wins. */\nexport function pluginReportedMaxOutput(headers: Record<string, string | string[] | undefined>): number | undefined {\n    const raw = pluginAgentHeader(headers) === undefined ? undefined : headerValue(headers, PLUGIN_MAX_OUTPUT_HEADER);\n    if (raw === undefined) return undefined;\n    const n = Number.parseInt(raw, 10);\n    return Number.isFinite(n) && n > 0 ? n : undefined;\n}\n\n/** Current model id (runtime-info protocol #955). Informational + lets the\n *  proxy correlate the per-agent runtime table with the request's model\n *  before trusting the table's window. Same plugin gate. */\nexport function pluginReportedModel(headers: Record<string, string | string[] | undefined>): string | undefined {\n    if (pluginAgentHeader(headers) === undefined) return undefined;\n    const raw = headerValue(headers, PLUGIN_MODEL_HEADER);\n    return raw !== undefined && /^\\S{1,256}$/.test(raw) ? raw : undefined;\n}\n\n/** #1699: per-request persona id, honored ONLY from an announced plugin (same\n *  gate as window/model): a plain client must not be able to change request\n *  classification by name. A real plugin stamps both headers. */\nexport function pluginRequestAgentHeader(headers: Record<string, string | string[] | undefined>): string | undefined {\n    if (pluginAgentHeader(headers) === undefined) return undefined;\n    return headerValue(headers, PLUGIN_REQUEST_AGENT_HEADER);\n}\n\n/** #4855: the plugin asks the proxy to serve compression on this request (identity + budget stay\n *  plugin-bound). Gated on the agent marker so a plain client cannot flip the channel by name. */\nexport function pluginCompressionProxyHeader(headers: Record<string, string | string[] | undefined>): boolean {\n    if (pluginAgentHeader(headers) === undefined) return false;\n    return headerValue(headers, PLUGIN_COMPRESSION_HEADER) === \"proxy\";\n}\n\n/** #956 hardening: per-request plugin window/max-output headers describe the\n *  model the plugin CONFIGURED — when the request body carries a different\n *  model (mid-switch race, or a provider-model composite like\n *  \"provider/model\"), those headers must not size this request. Match is\n *  exact or on the last path segment (openai-compatible bodies use\n *  \"provider/model\" while plugins stamp the bare model id). A missing model\n *  header keeps the pre-#956 trust (window-only reporters still work). */\nexport function pluginHeadersMatchModel(headers: Record<string, string | string[] | undefined>, bodyModel: string | undefined): boolean {\n    const reported = pluginReportedModel(headers);\n    if (reported === undefined || bodyModel === undefined) return true;\n    if (reported === bodyModel) return true;\n    return bodyModel.split(\"/\").pop() === reported;\n}\n\ntype ConversationEntry = { sessionId: string; lastSeen: number };\n\nconst MAX_PLUGIN_CONVERSATIONS = 1024;\n\n// #5753: the routing table rides the UNIFIED storage (kv_store namespace\n// \"plugin-conversations\", single row \"table\" holding id→{sessionId,lastSeen})\n// under the #5548 carrier rules: kv primary once hydrated, the legacy file\n// kept as pre-hydration fallback + sole carrier on legacy-only instances,\n// one-time migration on first hydration. Side benefit vs the file: sqlite\n// atomicity removes the torn-write class that spawned the .corrupt backups.\nconst CONV_NS = \"plugin-conversations\";\nconst CONV_KEY = \"table\";\nlet convKvReady = false;\nlet convChain: Promise<void> = Promise.resolve();\nlet convWarned = false;\n\nfunction convWarnOnce(tag: string, err: unknown): void {\n    if (convWarned) return;\n    convWarned = true;\n    loggerLog(\"warn\", `[plugin] ${tag} failed — the conversation table stays on the legacy file for this process (${err instanceof Error ? err.message : String(err)})`);\n}\n\n/** Validate a persisted table map; null unusable. Entries must carry a\n *  non-empty sessionId and a numeric lastSeen (the LRU clock depends on it). */\nfunction parseConvTable(value: unknown): Record<string, ConversationEntry> | null {\n    if (!value || typeof value !== \"object\" || Array.isArray(value)) return null;\n    const out: Record<string, ConversationEntry> = {};\n    for (const [k, v] of Object.entries(value as Record<string, unknown>)) {\n        if (!v || typeof v !== \"object\") continue;\n        const e = v as ConversationEntry;\n        if (typeof e.sessionId !== \"string\" || e.sessionId.length === 0) continue;\n        if (typeof e.lastSeen !== \"number\") continue;\n        out[k] = { sessionId: e.sessionId, lastSeen: e.lastSeen };\n    }\n    return out;\n}\n\nconst conversations = new Map<string, ConversationEntry>();\n// #2077: which content-store object each session's stored-refs list was last\n// evaluated against. Store updates are immutable (storeOriginal returns a new\n// object), so a changed object identity is the exact signal that the refs\n// list needs re-evaluation — an unchanged-view resend can skip even the refs\n// walk. Restored sessions are fresh objects, so their first remember\n// re-evaluates automatically.\nconst snapshotRefsEvaluatedStore = new WeakMap<Session, unknown>();\n\n// #1158: one-shot \"no model requests arrived\" warnings, keyed by conversation\n// id. A tool call proves the model already answered, so an id with ZERO model\n// requests means its traffic never reached this proxy (SDK-injected fetch,\n// e.g. dsh llm-pi-ai under a bare profile install) or is stale after a host\n// resume — warn once per conversation instead of on every rejected tool call.\nconst warnedNoModelRequests = new Set<string>();\nconst WARNED_NO_MODEL_REQUESTS_CAP = 4096;\n/** #1685 freshness window for single-active arbitration — same scale as the\n *  tool-witness TTL in tool-ring.ts. */\nconst WITNESS_TTL_MS_PLUGIN = 10 * 60 * 1000;\n\n// The conversationId → session mapping is in-memory. Persist it so a resumed\n// or restarted proxy can still resolve /acp + tool calls to the (persisted)\n// session without waiting for a fresh model request. Best-effort: a crash\n// before the debounced write just means the next model request repopulates it.\nconst conversationsFile = () => path.join(stateDir(), \"plugin-conversations.json\");\nlet conversationsSaveTimer: NodeJS.Timeout | undefined;\nlet conversationsDirty = false;\n\nfunction writeConversationsFile(): void {\n    if (!conversationsDirty) return;\n    try {\n        const obj: Record<string, ConversationEntry> = {};\n        for (const [k, v] of conversations) obj[k] = v;\n        // #5753: unified instances persist to kv_store — SQLite's atomic commit\n        // replaces the pid-tmp + fsync + rename dance below.\n        const store = kvStore();\n        if (convKvReady && store !== null) {\n            convChain = convChain.then(\n                () => store.setKvAsync(CONV_NS, CONV_KEY, obj),\n            ).catch((err) => {\n                convWarnOnce(\"persist\", err);\n                // #5757 review fix: a failed write DEMOTES this process back\n                // onto the legacy file path (the rescheduled save below takes\n                // it), instead of retrying a dead store on every 300ms save.\n                convKvReady = false;\n                conversationsDirty = true;\n                scheduleSaveConversations();\n            });\n            conversationsDirty = false;\n            return;\n        }\n        fs.mkdirSync(stateDir(), { recursive: true });\n        // #406: the only state file that used to be written in place — a\n        // torn write or a dying dual instance must not zero every route.\n        const filePath = conversationsFile();\n        const draft = `${filePath}.${process.pid}.bili-tmp`;\n        // fsync before rename: a crash between write and rename otherwise leaves\n        // a size-correct, VDL=0 zero file (#3157).\n        const fd = fs.openSync(draft, \"w\");\n        try {\n            fs.writeFileSync(fd, JSON.stringify(obj));\n            fs.fsyncSync(fd);\n        } finally {\n            fs.closeSync(fd);\n        }\n        fs.renameSync(draft, filePath);\n        conversationsDirty = false;\n    } catch {\n        // best-effort persistence; ignore write failures\n    }\n}\n\nfunction scheduleSaveConversations(): void {\n    if (conversationsSaveTimer) clearTimeout(conversationsSaveTimer);\n    conversationsSaveTimer = setTimeout(() => {\n        conversationsSaveTimer = undefined;\n        writeConversationsFile();\n    }, 300);\n}\n\n/** Flush the conversation map immediately (called on shutdown). Awaits queued\n *  unified-store writes so a graceful exit loses nothing. */\nexport async function flushConversations(): Promise<void> {\n    if (conversationsSaveTimer) {\n        clearTimeout(conversationsSaveTimer);\n        conversationsSaveTimer = undefined;\n    }\n    if (convKvReady && kvStore() !== null) {\n        if (conversationsDirty) writeConversationsFile(); // enqueue the queued table\n        await convChain;\n    } else {\n        writeConversationsFile();\n    }\n}\n\n/** Restore the persisted conversationId → session map. Called at startup,\n *  AFTER initSessions so the referenced sessions are already loaded. */\nexport function loadConversations(): void {\n    let raw: string;\n    try {\n        raw = fs.readFileSync(conversationsFile(), \"utf8\");\n    } catch {\n        return;\n    }\n    try {\n        const obj = JSON.parse(raw) as Record<string, ConversationEntry>;\n        for (const [k, v] of Object.entries(obj)) {\n            if (v && typeof v.sessionId === \"string\" && v.sessionId.length > 0) {\n                conversations.set(k, { sessionId: v.sessionId, lastSeen: typeof v.lastSeen === \"number\" ? v.lastSeen : Date.now() });\n            }\n        }\n    } catch {\n        // #406: preserve the corrupt bytes for forensics instead of\n        // silently zeroing every route on the next debounced write.\n        // #5779: bound the forensic retention like the session store does.\n        let removedCopies = 0;\n        try {\n            const backup = `${conversationsFile()}.corrupt-${Date.now()}`;\n            fs.renameSync(conversationsFile(), backup);\n            removedCopies = pruneCorruptSiblings(conversationsFile(), backup).removed;\n        } catch {}\n        const capNote = removedCopies > 0 ? `; removed ${removedCopies} older forensic cop${removedCopies === 1 ? \"y\" : \"ies\"} (cap ${CORRUPT_SIBLING_CAP})` : \"\";\n        loggerLog(\"warn\", `[plugin] plugin-conversations.json is corrupt — backed up beside the original, starting an empty routing table${capNote}`);\n    }\n    conversationsDirty = false;\n}\n\n/** Once per process (wired right after loadConversations at server start):\n *  layer the kv table over what loadConversations loaded (fresher lastSeen\n *  wins per id; oldest-first re-insertion restores the LRU clock), then\n *  migrate file-only rows into the store exactly once. Never throws. */\nexport async function hydratePluginConversationsUnified(): Promise<void> {\n    const store = kvStore();\n    if (convKvReady || !store) return;\n    try {\n        let raw: unknown;\n        try {\n            raw = await store.getKvAsync(CONV_NS, CONV_KEY);\n        } catch {\n            raw = undefined;\n        }\n        const hadRow = raw !== undefined && raw !== null;\n        const kvTable = hadRow ? (parseConvTable(raw) ?? {}) : {};\n        // kv ∪ file-loaded memory rows, fresher lastSeen wins per id…\n        const byKey = new Map<string, ConversationEntry>([...conversations]);\n        for (const [k, v] of Object.entries(kvTable)) {\n            const cur = byKey.get(k);\n            byKey.set(k, !cur || v.lastSeen >= cur.lastSeen ? v : cur);\n        }\n        // …re-insert oldest-first so the Map tail is most-recently-used again,\n        // then re-apply the cap from the front (oldest) like recordPluginSession.\n        const merged = [...byKey.entries()].sort((a, b) => a[1].lastSeen - b[1].lastSeen);\n        conversations.clear();\n        for (const [k, v] of merged) conversations.set(k, v);\n        while (conversations.size > MAX_PLUGIN_CONVERSATIONS) {\n            const oldest = conversations.keys().next().value;\n            if (oldest === undefined) break;\n            conversations.delete(oldest);\n        }\n        // One-time migration: rows loaded from the legacy file travel up once.\n        const missing = [...conversations.keys()].filter((k) => !(k in kvTable));\n        if (!hadRow || missing.length > 0) {\n            const payload: Record<string, ConversationEntry> = {};\n            for (const [k, v] of conversations) payload[k] = v;\n            await store.setKvAsync(CONV_NS, CONV_KEY, payload);\n            if (missing.length > 0) loggerLog(\"info\", `[plugin] migrated ${missing.length} conversation route(s) from the legacy JSON file into unified storage (#5753)`);\n        }\n        convKvReady = true;\n        conversationsDirty = false;\n    } catch (err) {\n        convWarnOnce(\"hydrate\", err);\n    }\n}\n\n/** Test seam: drop the unified caches; the next hydrate re-reads the volume. */\nexport function _resetPluginConversationsUnifiedForTest(): void {\n    convKvReady = false;\n    convChain = Promise.resolve();\n    convWarned = false;\n}\n\n/** Index a plugin session by its conversation id (the key the plugin uses on\n *  the tool API). Re-inserting moves the entry to the end so plain Map\n *  insertion order doubles as an LRU clock. Keys that name a resident session\n *  — or already carry a self-binding — are reserved: binding them to another\n *  session is forced back to the self-binding (#1895). */\nexport function recordPluginSession(conversationId: string, sessionId: string): void {\n    if (conversationId !== sessionId && (peekSession(conversationId) || conversations.get(conversationId)?.sessionId === conversationId)) {\n        sessionId = conversationId;\n    }\n    conversations.delete(conversationId);\n    conversations.set(conversationId, { sessionId, lastSeen: Date.now() });\n    conversationsDirty = true;\n    // remembered[sessionId] is intentionally left alone here: this runs OUTSIDE\n    // the session lock. rememberPluginMessages() rewrites it under the lock\n    // after forward(), and the tool API reads it under the lock — so no\n    // out-of-lock mutation that could leave a concurrent tool call on a stale\n    // (empty) snapshot.\n    if (conversations.size > MAX_PLUGIN_CONVERSATIONS) {\n        const oldest = conversations.keys().next().value;\n        if (oldest !== undefined) conversations.delete(oldest);\n    }\n    scheduleSaveConversations();\n}\n\ninterface PluginWireMetadata {\n    wireHash: string;\n    textComparable: boolean;\n}\n\n/** Capture the raw request's snapshot evidence before prepare mutates its\n *  parsed view. Only these scalars need to survive forwarding. */\nexport function preparePluginWireMetadata(rawWire: Buffer, parsedWire: unknown): PluginWireMetadata {\n    let textComparable = false;\n    try {\n        if (parsedWire !== null && typeof parsedWire === \"object\") {\n            const wire = parsedWire as Record<string, unknown>;\n            textComparable = comparableHistory(wire.messages ?? wire.input ?? wire.contents);\n        }\n    } catch {\n        textComparable = false;\n    }\n    return { wireHash: createHash(\"sha256\").update(rawWire).digest(\"hex\"), textComparable };\n}\n\n/** Keep the last prepare()'s view for a plugin session so tool-API execution\n *  sees the exact refs the model was shown (mirrors the wire-mode loop, which\n *  runs executeProxyTool against prepared.processedMessages). */\nexport function rememberPluginMessages(sessionId: string, processed: CoreMessage[], original: CoreMessage[], nudge?: NudgeDecision, rawWire?: Buffer | PluginWireMetadata): void {\n    // #1307: auxiliary requests (auto-review / classifier prompts) bound to the\n    // same session key can carry a normal output budget and any message count,\n    // so both the ≤200 heuristic and size-based guards are proxies that a new\n    // host shape walks through. The causal signal is IDENTITY: a main turn\n    // RESENDS the conversation, so it always carries messages the previous\n    // snapshot already holds (content-hash ids are stable); an auxiliary\n    // prompt shares NOTHING with it by construction. A zero-overlap view that\n    // is also smaller than the snapshot is therefore not a continuation —\n    // refuse to evict (the tool API anchors compress ranges from this\n    // snapshot; losing it dangles every long-session ref). Known cost: a\n    // genuine restart on the same session id keeps the stale snapshot for one\n    // round; the next resending turn self-heals. Fresh sessions and larger or\n    // overlapping views always write.\n    const incoming = processed.length > 0 ? processed : original;\n    const session = peekSession(sessionId);\n    if (!session) return;\n    const transient = session.transient ??= {};\n    const previous = transient.pluginMessages;\n    if (previous) {\n        const previousView = previous.processed.length > 0 ? previous.processed : previous.original;\n        if (previousView.length > incoming.length) {\n            const knownIds = new Set(previousView.map((m) => m.id));\n            if (!incoming.some((m) => knownIds.has(m.id))) return;\n        }\n    }\n    transient.pluginMessages = { processed, original, nudge };\n    if (typeof session.metadata.pluginAgent === \"string\" && original.length > 0) {\n        // #2077: copy-on-write snapshot maintenance. A raw id is a SHA-256 of\n        // the message identity plus a deterministic within-conversation\n        // duplicate-cluster index (acp-kernel wire/message-id.ts), but ids\n        // alone do NOT name the bytes: adapters attach wire flags outside the\n        // CoreMessage interface (toolIsError — see forkToolIsError), so the\n        // walk below compares full views (sameSnapshotView: exactly the field\n        // set forkMessageIdentityHash digests, plus id). Steady state costs a\n        // field scan instead of clone + serialize: a pure extension clones\n        // only its tail and extends the tracked byte count rather than\n        // re-cloning and re-serializing the whole history every request.\n        const cap = publicSnapshotCapBytes();\n        const dropOverCap = () => {\n            session.pluginSnapshot = undefined;\n            session.metadata.publicSnapshotCapped = true;\n            delete session.metadata.publicSnapshotBytes;\n        };\n        let changed = false;\n        const prev = session.pluginSnapshot;\n        if (!prev || session.metadata.publicSnapshotCapped === true) {\n            // First write (fresh session, lazy-persist restore gap) or recovery\n            // after a cap-drop. Measure BEFORE cloning so an over-cap history\n            // pays one serialize, not clone + serialize.\n            const bytes = stableJson(original).length;\n            if (cap > 0 && bytes > cap) dropOverCap();\n            else {\n                session.pluginSnapshot = structuredClone(original);\n                session.metadata.publicSnapshotBytes = bytes;\n                delete session.metadata.publicSnapshotCapped;\n            }\n            changed = true;\n        } else {\n            const n = original.length;\n            let k = 0;\n            while (k < prev.length && k < n && sameSnapshotView(prev[k], original[k])) k++;\n            if (k === n && n === prev.length) {\n                // Identical view (e.g. an upstream retry re-forwarding the\n                // same body): snapshot, byte count and refs list stay valid,\n                // and skipping markDirty keeps the revision cache warm so\n                // status polls stay O(1). The cap is still enforced from the\n                // tracked count on every request, and legacy records predate\n                // the count — measure them once into it.\n                const trackedBytes = typeof session.metadata.publicSnapshotBytes === \"number\" ? session.metadata.publicSnapshotBytes : undefined;\n                const bytes = trackedBytes ?? stableJson(prev).length;\n                if (trackedBytes === undefined) session.metadata.publicSnapshotBytes = bytes;\n                if (cap > 0 && bytes > cap) dropOverCap();\n                if (trackedBytes === undefined || cap > 0 && bytes > cap) changed = true;\n            } else if (k === prev.length) {\n                // Pure extension: append the tail (per-element clones keep the\n                // snapshot independent of the request's live arrays) and extend\n                // the byte count incrementally — appending an element e to an\n                // array A grows len(sj(A)) by len(sj(e)) + 1 (its serialization\n                // plus one separating comma), so no re-serialization is needed.\n                let bytes = typeof session.metadata.publicSnapshotBytes === \"number\"\n                    ? session.metadata.publicSnapshotBytes\n                    : stableJson(prev).length;\n                for (let i = k; i < n; i++) bytes += stableJson(original[i]).length + 1;\n                if (cap > 0 && bytes > cap) dropOverCap();\n                else {\n                    for (let i = k; i < n; i++) prev.push(structuredClone(original[i]));\n                    session.metadata.publicSnapshotBytes = bytes;\n                    delete session.metadata.publicSnapshotCapped;\n                }\n                changed = true;\n            } else {\n                // Replacement (compression rewrote the history, restart\n                // divergence): full rebuild, measured before cloning as above.\n                const bytes = stableJson(original).length;\n                if (cap > 0 && bytes > cap) dropOverCap();\n                else {\n                    session.pluginSnapshot = structuredClone(original);\n                    session.metadata.publicSnapshotBytes = bytes;\n                    delete session.metadata.publicSnapshotCapped;\n                }\n                changed = true;\n            }\n        }\n        // The refs list must re-evaluate whenever the store object changed —\n        // CCR can gain entries between remembers without any history change,\n        // and the fork-time fail-closed check reads this list against the\n        // CURRENT store.\n        const storeChanged = snapshotRefsEvaluatedStore.get(session) !== session.contentStore;\n        if (changed || storeChanged) {\n            const previousRefs = session.metadata.publicSnapshotStoredRefs;\n            session.metadata.publicSnapshotStoredRefs = [...new Set([\n                ...(Array.isArray(previousRefs) ? previousRefs : []),\n                ...(session.pluginSnapshot ?? []).flatMap((m) => {\n                    const ref = session.state.messageRefs.byRaw[m.id];\n                    return ref && session.contentStore?.byRef[ref] ? [ref] : [];\n                }),\n            ])];\n            snapshotRefsEvaluatedStore.set(session, session.contentStore);\n        }\n        if (rawWire !== undefined) {\n            // The handler captures this evidence before forwarding so it need\n            // not retain the raw body. Buffer callers keep the hash-gated parse.\n            const wireHash = Buffer.isBuffer(rawWire)\n                ? createHash(\"sha256\").update(rawWire).digest(\"hex\")\n                : rawWire.wireHash;\n            if (session.metadata.publicSnapshotWireHash !== wireHash) {\n                let comparable: boolean;\n                if (Buffer.isBuffer(rawWire)) {\n                    try {\n                        const wire = JSON.parse(rawWire.toString(\"utf8\")) as Record<string, unknown>;\n                        comparable = comparableHistory(wire.messages ?? wire.input ?? wire.contents);\n                    } catch {\n                        comparable = false;\n                    }\n                } else {\n                    comparable = rawWire.textComparable;\n                }\n                session.metadata.publicSnapshotWireHash = wireHash;\n                if (session.metadata.publicSnapshotTextComparable !== comparable) {\n                    session.metadata.publicSnapshotTextComparable = comparable;\n                    changed = true;\n                }\n            }\n        }\n        if (changed || storeChanged) markDirty(session);\n    }\n}\n\n// Launcher mode (#162): hosts that cannot attach per-request headers\n// (claude/codex spawned by `bili claude` / `bili codex`) pre-register their\n// conversation via POST /__bili/plugin/register — typically from a Claude\n// Code SessionStart hook or at codex spawn time. A pending register is\n// consumed by the FIRST model request that creates a NEW session afterwards\n// (server.ts binding step): that session becomes plugin-mode (native tools,\n// wire injection suppressed) and the conversation id becomes its tool-API key\n// — no x-bili-plugin headers required.\ntype PendingPluginRegister = { conversationId: string; agent: string; ts: number; parentConversationId?: string };\n\n/** Runtime-info protocol entry (#955): what the client's OWN config says it\n *  will run — reported at plugin bootstrap and on model switch, before (and\n *  independent of) any model request. Ranked in the native-window chain\n *  directly under the per-request header report; entries carry their model\n *  id and are only usable when that id matches the request's model (a stale\n *  post-switch entry must never size a different model). Entries carrying a\n *  conversationId are keyed by it (#1531), not by agent — one process runs\n *  many sessions (main + subagents) that share the agent name but report\n *  different windows, and a single per-agent slot let the last reporter\n *  clobber everyone else's entry. */\ntype PluginRuntimeInfo = {\n    agent: string;\n    model: string;\n    contextWindow?: number;\n    maxOutput?: number;\n    baseURL?: string;\n    conversationId?: string;\n    source: string;\n    ts: number;\n};\n\nconst pluginRuntimeTable = new Map<string, PluginRuntimeInfo>();\nconst pluginRuntimeByConversation = new Map<string, PluginRuntimeInfo>();\nconst MAX_PLUGIN_RUNTIME_ENTRIES = 32;\n\nfunction evictOldestRuntimeEntries(map: Map<string, PluginRuntimeInfo>): void {\n    while (map.size > MAX_PLUGIN_RUNTIME_ENTRIES) {\n        const oldest = map.keys().next().value;\n        if (oldest === undefined) break;\n        map.delete(oldest);\n    }\n}\n\nexport function recordPluginRuntimeInfo(entry: PluginRuntimeInfo): void {\n    const conv = entry.conversationId !== undefined && entry.conversationId.length > 0 ? entry.conversationId : undefined;\n    const table = conv !== undefined ? pluginRuntimeByConversation : pluginRuntimeTable;\n    table.delete(conv ?? entry.agent);\n    table.set(conv ?? entry.agent, entry);\n    evictOldestRuntimeEntries(table);\n}\n\n/** Latest runtime-info for an agent, usable for `model` only (undefined =\n *  no report, or a report for a different model). */\nexport function pluginRuntimeInfoFor(agent: string | undefined, model: string | undefined): PluginRuntimeInfo | undefined {\n    if (agent === undefined || model === undefined) return undefined;\n    const entry = pluginRuntimeTable.get(agent);\n    if (entry === undefined || entry.model !== model) return undefined;\n    return entry;\n}\n\n/** Clients mint child conversation ids for work that runs on the parent's own\n *  route+model: omp opens ephemeral turns as `<session>:side:<id>` and\n *  subagents as `<session>:sub:<id>` (with `:side:conversation:<key>` also\n *  seen in the wild), and never registers runtime-info under them — the\n *  window belongs to route+model+tier, so a child resolves up to the nearest\n *  ancestor that reported one instead of falling to the registry/#1321 cap. */\nconst CHILD_CONVERSATION_SUFFIX = /:(?:side(?::conversation)?|sub):[^:]+$/;\nconst MAX_CHILD_CONVERSATION_DEPTH = 4;\n\nfunction parentConversationId(conversationId: string): string | undefined {\n    const parent = conversationId.replace(CHILD_CONVERSATION_SUFFIX, \"\");\n    return parent !== conversationId && parent.length > 0 ? parent : undefined;\n}\n\n/** Latest runtime-info registered under a conversation id, usable for\n *  `model` only (#1531). A client-minted child id resolves to its nearest\n *  reporting ancestor; the model check is applied at whichever level answers,\n *  so a child on a different model never inherits a stale window. */\nexport function pluginRuntimeInfoForConversation(conversationId: string | undefined, model: string | undefined): PluginRuntimeInfo | undefined {\n    if (conversationId === undefined || model === undefined) return undefined;\n    const exact = pluginRuntimeByConversation.get(conversationId);\n    if (exact !== undefined) return exact.model === model ? exact : undefined;\n    let parent = parentConversationId(conversationId);\n    for (let depth = 0; parent !== undefined && depth < MAX_CHILD_CONVERSATION_DEPTH; depth++) {\n        const entry = pluginRuntimeByConversation.get(parent);\n        if (entry !== undefined) return entry.model === model ? entry : undefined;\n        parent = parentConversationId(parent);\n    }\n    return undefined;\n}\n\n/** The narrow conversation signal a header-less runtime-info lookup can\n *  match on (#1531): client conversation header → custom session header →\n *  body prompt_cache_key. Mirrors the identity chain's precedence at exactly\n *  the points where a reported conversationId could have been minted (omp\n *  stamps prompt_cache_key with its session uuid, #957/#1230); any divergence\n *  from the full binding identity degrades to a miss — legacy behavior —\n *  never a wrong hit. */\nexport function runtimeConversationId(headers: Record<string, string | string[] | undefined>, parsed: unknown, sessionHeaderName?: string): string | undefined {\n    const fromClient = clientConversationHeader(headers);\n    if (fromClient !== undefined && fromClient.length > 0) return fromClient;\n    const custom = sessionHeaderName !== undefined ? headerValue(headers, sessionHeaderName) : undefined;\n    if (custom !== undefined) return custom;\n    const pck = typeof parsed === \"object\" && parsed !== null ? (parsed as { prompt_cache_key?: unknown }).prompt_cache_key : undefined;\n    return typeof pck === \"string\" && pck.trim().length > 0 ? pck.trim() : undefined;\n}\n\n/** Accept the bootstrap/model-switch report. Body:\n *  { agent, model, contextWindow?, maxOutput?, baseURL?, source?,\n *    conversationId? } — agent+model are required; numbers are validated.\n *  Loopback-gated like every /__bili/plugin/* endpoint (the route lives\n *  under the same admin gate in server.ts). */\nexport function handlePluginRuntimeInfo(payload: string, res: import(\"node:http\").ServerResponse): void {\n    let parsed: unknown;\n    try {\n        parsed = JSON.parse(payload);\n    } catch {\n        res.writeHead(400, { \"content-type\": \"application/json\" });\n        res.end(JSON.stringify({ ok: false, error: \"invalid JSON\" }));\n        return;\n    }\n    const body = parsed as { agent?: unknown; model?: unknown; contextWindow?: unknown; maxOutput?: unknown; baseURL?: unknown; conversationId?: unknown; source?: unknown };\n    const str = (v: unknown, max: number) => (typeof v === \"string\" && v.length > 0 && v.length <= max ? v : undefined);\n    const num = (v: unknown) => (typeof v === \"number\" && Number.isFinite(v) && v > 0 ? Math.floor(v) : undefined);\n    const agent = str(body.agent, 64);\n    const model = str(body.model, 256);\n    if (agent === undefined || model === undefined) {\n        res.writeHead(400, { \"content-type\": \"application/json\" });\n        res.end(JSON.stringify({ ok: false, error: \"agent and model are required\" }));\n        return;\n    }\n    const conversationId = str(body.conversationId, 256);\n    recordPluginRuntimeInfo({\n        agent,\n        model,\n        contextWindow: num(body.contextWindow),\n        maxOutput: num(body.maxOutput),\n        baseURL: str(body.baseURL, 2048),\n        ...(conversationId !== undefined ? { conversationId } : {}),\n        source: str(body.source, 64) ?? \"client-config\",\n        ts: Date.now(),\n    });\n    res.writeHead(200, { \"content-type\": \"application/json\" });\n    res.end(JSON.stringify({ ok: true }));\n}\n\n/** Accept a takeover-attribution health report (#3581, contract reworked by\n *  #3651). Body: { agent, state: \"ok\"|\"none\"|\"threw\", refusals, since,\n *  [error], [endpoint] } — under the #3651 owner contract only DIAGNOSABLE\n *  failures (`threw` episodes: first refusal, state change to threw, count\n *  doubling, give-up latch) plus recovery notices reach this route; by-design\n *  agentless lanes never report. `error`/`endpoint` are bounded diagnostics\n *  that make the panel banner name the failure instead of a generic\n *  \"takeover broken\". Latest report wins per agent; the payload feeds\n *  /__bili/status + /__bili/overview (`attribution` field) and the web panel\n *  banner. */\nexport function handlePluginAttribution(payload: string, res: import(\"node:http\").ServerResponse): void {\n    let parsed: unknown;\n    try {\n        parsed = JSON.parse(payload);\n    } catch {\n        res.writeHead(400, { \"content-type\": \"application/json\" });\n        res.end(JSON.stringify({ ok: false, error: \"invalid JSON\" }));\n        return;\n    }\n    const body = parsed as { agent?: unknown; state?: unknown; refusals?: unknown; since?: unknown; error?: unknown; endpoint?: unknown };\n    const str = (v: unknown, max: number) => (typeof v === \"string\" && v.length > 0 && v.length <= max ? v : undefined);\n    const nonNeg = (v: unknown) => (typeof v === \"number\" && Number.isFinite(v) && v >= 0 ? Math.floor(v) : undefined);\n    const agent = str(body.agent, 64);\n    if (agent === undefined || (body.state !== \"ok\" && body.state !== \"none\" && body.state !== \"threw\")) {\n        res.writeHead(400, { \"content-type\": \"application/json\" });\n        res.end(JSON.stringify({ ok: false, error: \"agent and state (ok|none|threw) are required\" }));\n        return;\n    }\n    const error = str(body.error, 300);\n    const endpoint = str(body.endpoint, 200);\n    recordAttributionReport(agent, {\n        state: body.state,\n        refusals: nonNeg(body.refusals) ?? 0,\n        since: nonNeg(body.since) ?? 0,\n        ...(error !== undefined ? { error } : {}),\n        ...(endpoint !== undefined ? { endpoint } : {}),\n    });\n    res.writeHead(200, { \"content-type\": \"application/json\" });\n    res.end(JSON.stringify({ ok: true }));\n}\n\nconst MAX_PENDING_REGISTERS = 64;\n\nconst pendingRegisters: PendingPluginRegister[] = [];\n\n/** Queue a launcher-mode registration. `identity: true` means the host puts\n *  the SAME id on every model request (claude code: x-claude-code-session-id\n *  === CLAUDE_CODE_SESSION_ID) — bind by identity match only. `identity:\n *  false` (headless codex spawn) means requests carry no matching id — bind\n *  the next NEW session instead. Splitting the two keeps a foreign session\n *  from eating an identity registration it can never claim. */\nexport function queuePluginRegister(conversationId: string, agent: string, identity: boolean, parentConversationId?: string): void {\n    if (!identity) {\n        for (let i = 0; i < pendingRegisters.length; i++) {\n            if (pendingRegisters[i]!.conversationId === conversationId) {\n                pendingRegisters.splice(i, 1);\n                break;\n            }\n        }\n        pendingRegisters.push({ conversationId, agent, ts: Date.now(), ...(parentConversationId ? { parentConversationId } : {}) });\n        while (pendingRegisters.length > MAX_PENDING_REGISTERS) pendingRegisters.shift();\n    } else {\n        // #2408: a parent declaration is sticky for a conversation — a\n        // follow-up register WITHOUT one (claude's MCP shim re-registering the\n        // session the fork hook already declared) must not erase it.\n        const parent = parentConversationId ?? registeredIds.get(conversationId)?.parentConversationId;\n        registeredIds.set(conversationId, { agent, ...(parent ? { parentConversationId: parent } : {}) });\n        while (registeredIds.size > MAX_PENDING_REGISTERS) {\n            const oldest = registeredIds.keys().next().value;\n            if (oldest !== undefined) registeredIds.delete(oldest);\n        }\n    }\n}\n\n/** Headless registrations expire: a registration that no new session has\n *  claimed within this window was orphaned (the spawn never happened, or the\n *  session was created by some other path). Binding a stale one to an\n *  unrelated later session would turn that session into plugin mode with a\n *  foreign conversation id. */\nconst PENDING_REGISTER_TTL_MS = 10 * 60 * 1000;\n\n/** Take (and remove) the oldest eligible pending registration — called by the\n *  server when a model request resolves a NEW session, to bind that session\n *  into plugin mode. Expired (orphaned) registrations are dropped, never\n *  bound. Entries are appended in time order, so pruning from the front\n *  suffices. */\nexport function takePendingPluginRegister(\n    eligible: (pending: PendingPluginRegister) => boolean = () => true,\n): PendingPluginRegister | undefined {\n    const now = Date.now();\n    while (pendingRegisters.length > 0 && now - pendingRegisters[0]!.ts > PENDING_REGISTER_TTL_MS) {\n        pendingRegisters.shift();\n    }\n    const index = pendingRegisters.findIndex(eligible);\n    return index < 0 ? undefined : pendingRegisters.splice(index, 1)[0];\n}\nconst registeredIds = new Map<string, { agent: string; parentConversationId?: string }>();\n\n/** Identity-driven binding (#162): hosts whose model requests carry the SAME\n *  id the MCP shell registered (claude code: every request has\n *  x-claude-code-session-id === CLAUDE_CODE_SESSION_ID === the registered\n *  conversation id) bind the moment any of their requests shows up — no\n *  ordering race with the shell's initialize. */\nexport function consumePluginRegisterFor(conversationId: string): { agent: string; parentConversationId?: string } | undefined {\n    const entry = registeredIds.get(conversationId);\n    if (entry !== undefined) {\n        // The registration describes the CONVERSATION, not a one-shot token:\n        // switching models/upstreams mid-conversation resolves to a NEW\n        // session (session key = protocol|upstream|apiKey|conversation) that\n        // must still bind — omp TUI flows that switch models would otherwise\n        // drop back to wire mode on every switch. Keep the entry and refresh\n        // LRU order so the size cap evicts least-recently-active conversations.\n        registeredIds.delete(conversationId);\n        registeredIds.set(conversationId, entry);\n    }\n    return entry;\n}\n\nexport function handlePluginRegister(payload: string, res: import(\"node:http\").ServerResponse): void {\n    let parsed: { conversationId?: unknown; agent?: unknown; identity?: unknown; parentConversationId?: unknown };\n    try {\n        parsed = JSON.parse(payload) as { conversationId?: unknown; agent?: unknown; identity?: unknown };\n    } catch {\n        res.writeHead(400, { \"content-type\": \"application/json\" });\n        res.end(JSON.stringify({ ok: false, error: \"invalid JSON body\" }));\n        return;\n    }\n    const conversationId = typeof parsed.conversationId === \"string\" ? parsed.conversationId.trim() : \"\";\n    if (!conversationId) {\n        res.writeHead(400, { \"content-type\": \"application/json\" });\n        res.end(JSON.stringify({ ok: false, error: \"conversationId is required\" }));\n        return;\n    }\n    const agent = typeof parsed.agent === \"string\" && parsed.agent.trim() ? parsed.agent.trim() : \"launcher\";\n    // [#1333] optional declared derivation (pi RLM child): the parent\n    // conversation the proxy should seed this conversation from.\n    let parentConversationId = typeof parsed.parentConversationId === \"string\" ? parsed.parentConversationId.trim() : \"\";\n    if (parentConversationId === conversationId) parentConversationId = \"\";\n    queuePluginRegister(conversationId, agent, parsed.identity === true, parentConversationId || undefined);\n    res.end(JSON.stringify({ ok: true, conversationId, agent }));\n}\n\nexport function handlePluginCompact(payload: string, res: import(\"node:http\").ServerResponse): void {\n    let parsed: { conversationId?: unknown };\n    try {\n        parsed = JSON.parse(payload) as { conversationId?: unknown };\n    } catch {\n        res.writeHead(400, { \"content-type\": \"application/json\" });\n        res.end(JSON.stringify({ ok: false, error: \"invalid JSON body\" }));\n        return;\n    }\n    const conversationId = typeof parsed.conversationId === \"string\" ? parsed.conversationId.trim() : \"\";\n    if (!conversationId) {\n        res.writeHead(400, { \"content-type\": \"application/json\" });\n        res.end(JSON.stringify({ ok: false, error: \"conversationId is required\" }));\n        return;\n    }\n    const { session, entry } = resolveConversation(conversationId);\n    // #760: the verbatim-id fallback above can resolve a session with NO map\n    // entry (first call), so only the session itself gates execution.\n    if (!session) {\n        res.writeHead(404, { \"content-type\": \"application/json\" });\n        res.end(JSON.stringify({\n            ok: false,\n            error: entry\n                ? `unknown plugin conversation id \"${conversationId}\" (id registered but session not resident)`\n                : `unknown plugin conversation id \"${conversationId}\" (no model request has arrived with this conversation id yet)`,\n        }));\n        return;\n    }\n    markCompactionBoundary(session);\n    if (entry) entry.lastSeen = Date.now();\n    res.end(JSON.stringify({ ok: true, conversationId }));\n}\n\n// #2322: the host named the conversation (pi /name) — remember it as the\n// session's display title. B-channel design: a dedicated endpoint (instead\n// of a request header) so set/rename/CLEAR are all expressible (empty name =\n// clear, falling display back to the derived first-message title) and the\n// name lands immediately, not on the next model request.\nconst HOST_TITLE_MAX = 200;\n\nexport function handlePluginSessionName(payload: string, res: import(\"node:http\").ServerResponse): void {\n    let parsed: { conversationId?: unknown; name?: unknown };\n    try {\n        parsed = JSON.parse(payload) as { conversationId?: unknown; name?: unknown };\n    } catch {\n        res.writeHead(400, { \"content-type\": \"application/json\" });\n        res.end(JSON.stringify({ ok: false, error: \"invalid JSON body\" }));\n        return;\n    }\n    const conversationId = typeof parsed.conversationId === \"string\" ? parsed.conversationId.trim() : \"\";\n    if (!conversationId) {\n        res.writeHead(400, { \"content-type\": \"application/json\" });\n        res.end(JSON.stringify({ ok: false, error: \"conversationId is required\" }));\n        return;\n    }\n    if (typeof parsed.name !== \"string\") {\n        res.writeHead(400, { \"content-type\": \"application/json\" });\n        res.end(JSON.stringify({ ok: false, error: \"name must be a string (empty clears)\" }));\n        return;\n    }\n    const { session, entry } = resolveConversation(conversationId);\n    if (!session) {\n        res.writeHead(404, { \"content-type\": \"application/json\" });\n        res.end(JSON.stringify({\n            ok: false,\n            error: entry\n                ? `unknown plugin conversation id \"${conversationId}\" (id registered but session not resident)`\n                : `unknown plugin conversation id \"${conversationId}\" (no model request has arrived with this conversation id yet)`,\n        }));\n        return;\n    }\n    let name = parsed.name.replace(/\\s+/g, \" \").trim();\n    if (name.length > HOST_TITLE_MAX) name = name.slice(0, HOST_TITLE_MAX);\n    if (name) session.meta.hostTitle = name;\n    else delete session.meta.hostTitle;\n    markDirty(session);\n    if (entry) entry.lastSeen = Date.now();\n    res.end(JSON.stringify({ ok: true, conversationId }));\n}\n\n// #1685: the conversation_id tool parameter is GONE from the manifest — the\n// model must never see or echo a conversation id (zero-injection identity:\n// the proxy routes by outbound tool_use witness / body id / single-active\n// arbitration; see tool-ring.ts). Wire-mode injection serves the kernel\n// constants directly, which never carried the param.\n\nexport function handlePluginManifest(res: import(\"node:http\").ServerResponse, config: Config, toolPrompts?: ToolPrompts): void {\n    // #1192: hosts register whatever the manifest serves verbatim (pi/omp/dsh/\n    // opencode native plugins, MCP shims), so advertising an opt-in tool this\n    // proxy's config leaves disabled guarantees a rejected call the moment the\n    // model uses it. Advertise absorb/acp_rule only when base-config enabled;\n    // per-request provider/model overrides may still differ (conservative: the\n    // manifest never advertises what the base config disables) and per-session\n    // enablement stays enforced at execution (isProxyToolFor / executeProxyTool).\n    // #1359: the advertised name is the base-config toolName, matching the\n    // plugin-lane gate (which adjudicates the same base block).\n    // #3243: toolPrompts is the pack surface's tool descriptions, resolved by the\n    // caller from the GLOBAL compress settings — the manifest has no route/model\n    // context (hosts fetch it before any request arrives), so provider/model-level\n    // promptPack still shapes each request's system prompt while registered tool\n    // descriptions follow the top-level pack only. Applied exactly like the wire\n    // injector (applyAcpToolOverrides on the ACP core arrays before extras merge).\n    const absorbOn = absorbEnabled(config);\n    const absorbName = config.absorb?.toolName ?? ABSORB_TOOL_NAME;\n    const absorbTools = absorbOn ? absorbToolsFor(absorbName) : undefined;\n    // #5765: block-lifecycle tools — one switch (compress.blockOps.enabled),\n    // off by default; same conservative #1192 manifest rule as absorb (base\n    // config, no route/model context here).\n    const blockOpsOn = blockOpsEnabled(config);\n    const blockOps = blockOpsOn ? blockOpsTools() : undefined;\n    const rulesOn = rulesEnabled(config);\n    // [#1271] acp_retrieve is advertised only while the base config enables CCR (same\n    // #1192 conservative rule as absorb/acp_rule). The proxy wires it on the anthropic/\n    // openai lanes in plugin mode; the responses wire is deliberately NOT advertised —\n    // that proxy disarms CCR there, so advertising would break #1192.\n    const ccrOn = config.ccr?.enabled === true;\n    const ccrName = config.ccr?.toolName ?? RETRIEVE_TOOL_NAME;\n    const ccrTools = ccrOn ? retrieveToolsFor(ccrName) : undefined;\n    // #3400: acp_read_original_image restores the full-resolution original of a\n    // downscaled image from local session storage. Same conservative #1192\n    // rule as acp_retrieve: advertised only while the base knob enables the\n    // rescale pass (disabled ⇒ no [bili] note ever names it, so a registered\n    // copy could only be dead weight). Execution stays always-allowed: it is\n    // an idempotent local read, never a state mutation.\n    const rescaleOn = imageRescaleEnabled();\n    // #1712: decompress's startId/endId (range restore) executes only on CCR-armed\n    // sessions, so the manifest advertises them only when the base config enables\n    // CCR (#1345 plugin policy = base block verbatim) — same conservative #1192\n    // rule as acp_retrieve above. CCR-off manifests serve the no-range variants so\n    // a registered agent never sees range fields execution would refuse.\n    const externalSummary = externalSummaryEnabled(config);\n    // #3252: the manifest serves code-mode harnesses too (dsh registers the\n    // dsh-bili plugin and its \"PTC\" preset renders these descriptions as the\n    // run_code SDK docs). The binding note on the ACP entries teaches both\n    // calling conventions, so the model neither slips a direct call the\n    // harness will reject nor dodges the direct call native hosts expect.\n    // #3243: the pack surface's tool descriptions (toolPrompts) override the\n    // stock descriptions where a promptPack declares its own.\n    const acpAnthropic = withAcpNotes(withExternalSummaryTools(applyAcpToolOverrides(ccrOn ? BILI_ACP_TOOLS_ANTHROPIC : BILI_ACP_TOOLS_ANTHROPIC_NO_RANGE, toolPrompts), externalSummary), \"binding\");\n    const acpOpenai = withAcpNotesOpenAI(withExternalSummaryTools(applyAcpToolOverrides(ccrOn ? BILI_ACP_TOOLS_OPENAI : BILI_ACP_TOOLS_OPENAI_NO_RANGE, toolPrompts), externalSummary), \"binding\");\n    // Responses wire: plugin mode structurally disarms CCR there (#1271 —\n    // PLUGIN_CCR_WIRES excludes it), so range restore can never execute for a\n    // registered agent on that wire — always the no-range variant, mirroring\n    // how ccrTools above is never spread into the responses array.\n    const acpResponses = withAcpNotes(withExternalSummaryTools(applyAcpToolOverrides(BILI_ACP_TOOLS_RESPONSES_NO_RANGE, toolPrompts), externalSummary), \"binding\");\n    res.writeHead(200, { \"content-type\": \"application/json\" });\n    res.end(JSON.stringify({\n        ok: true,\n        protocolVersion: PLUGIN_PROTOCOL_VERSION,\n        proxy: \"billion-context\",\n        version: VERSION,\n        commit: BUILD_COMMIT,\n        toolNames: [...PROXY_TOOL_NAMES, ...(absorbTools ? [absorbName] : []), ...(rulesOn ? [RULE_TOOL_NAME] : []), ...(ccrOn ? [ccrName] : []), ...(rescaleOn ? [READ_ORIGINAL_IMAGE_TOOL_NAME] : []), ...(blockOpsOn ? [ACP_RETIRE_TOOL_NAME, ACP_RESTORE_TOOL_NAME, ACP_REWRITE_TOOL_NAME] : [])],\n        tools: {\n            anthropic: [...acpAnthropic, ...(absorbTools ? [absorbTools.anthropic] : []), ...(rulesOn ? [RULE_TOOL] : []), ...(ccrTools ? [ccrTools.anthropic] : []), ...(rescaleOn ? [READ_ORIGINAL_IMAGE_TOOL] : []), ...(blockOps ? blockOps.anthropic : [])],\n            openai: [...acpOpenai, ...(absorbTools ? [absorbTools.openai] : []), ...(rulesOn ? [RULE_TOOL_OPENAI] : []), ...(ccrTools ? [ccrTools.openai] : []), ...(rescaleOn ? [READ_ORIGINAL_IMAGE_TOOL_OPENAI] : []), ...(blockOps ? blockOps.openai : [])],\n            responses: [...acpResponses, ...(absorbTools ? [absorbTools.responses] : []), ...(rulesOn ? [RULE_TOOL_RESPONSES] : []), ...(rescaleOn ? [READ_ORIGINAL_IMAGE_TOOL_RESPONSES] : []), ...(blockOps ? blockOps.responses : [])],\n        },\n        headers: { agent: PLUGIN_AGENT_HEADER, conversation: PLUGIN_CONVERSATION_HEADER, contextWindow: PLUGIN_CONTEXT_WINDOW_HEADER, maxOutput: PLUGIN_MAX_OUTPUT_HEADER, model: PLUGIN_MODEL_HEADER, instructionsMutable: PLUGIN_INSTRUCTIONS_MUTABLE_HEADER, compression: PLUGIN_COMPRESSION_HEADER },\n        toolEndpoint: \"/__bili/plugin/tool\",\n        statusEndpoint: \"/__bili/plugin/status\",\n        runtimeInfoEndpoint: \"/__bili/plugin/runtime-info\",\n        // #2652: maxToolDurationMs = the budget's totalTimeoutMs ceiling, so agent-side\n        // bridges size their compress-call HTTP wait to the real server bound instead of a\n        // fixed constant. Absent when the chain is off (classic summaries commit locally).\n        capabilities: { ...(externalSummary ? { externalSummary: { enabled: true, summaryOptional: true, submittedSummary: \"hint\", maxToolDurationMs: externalSummaryMaxToolDurationMs(config) } } : {}), fork: { protocolVersion: 2, acceptsProtocolVersions: [1, 2], endpoint: \"/__bili/plugin/fork\", snapshotEndpoint: \"/__bili/plugin/snapshot\" } },\n    }));\n}\n\nexport type PluginToolDeps = {\n    core: CompressionCore;\n    config: Config;\n    log: (level: string, msg: string) => void;\n    // Browser-reachable origin of THIS proxy (http://host:port) for the human-facing\n    // Web UI deep links inside panels/reports; absent in test harnesses/embeds.\n    webOrigin?: string;\n    // #4571: true when the answering engine is the in-process inline lane —\n    // the status panel appends \" · inline\" so a screenshot names its mode.\n    inlineLane?: boolean;\n    signal?: AbortSignal;\n};\n\n/** Reverse-lookup the conversation id bound to a session id. #656: the\n *  status endpoint's fallback branch picks the latest active SESSION, but a\n *  caller that needs to ADOPT it (an MCP shim whose captured conversation id\n *  went stale after the host resumed) must be told the session's conversation\n *  id, not have its own stale id echoed back. Most-recently-seen binding wins\n *  when several conversations share one session. */\nfunction conversationIdForSession(sessionId: string): string | undefined {\n    let bestId: string | undefined;\n    let bestSeen = -Infinity;\n    for (const [cid, entry] of conversations) {\n        if (entry.sessionId === sessionId && entry.lastSeen > bestSeen) {\n            bestId = cid;\n            bestSeen = entry.lastSeen;\n        }\n    }\n    return bestId;\n}\n\n/** Native session ids outrank lookup aliases: shared prompt_cache_key values\n *  must not redirect a parent to a child. Repair legacy conflicting mappings\n *  on lookup; unknown ids still create no session. */\nexport function resolveConversation(conversationId: string): { session: Session | undefined; entry?: ConversationEntry } {\n    let entry = conversations.get(conversationId);\n    let session = peekSession(conversationId) ?? (entry ? peekSession(entry.sessionId) : undefined);\n    if (!session) {\n        session = findSessionByCanonicalId(conversationId);\n    }\n    if (session && entry?.sessionId !== session.id) {\n        recordPluginSession(conversationId, session.id);\n        entry = conversations.get(conversationId);\n    }\n    return { session, entry };\n}\n\n// #2620: ref is null exactly when the message is intentionally unaddressable\n// (kernel-protected: no numeric ref issued). The kernel's internal sentinel\n// never crosses this boundary — null IS the protocol's \"no ref\" value.\ntype ForkIdentity = { rawId: string; ref: string | null; identityHash: string };\n\n// Only inspect message content, not arbitrary tool arguments containing a `type` key.\nfunction comparableHistory(value: unknown): boolean {\n    if (value === null || typeof value === \"string\") return true;\n    if (Array.isArray(value)) return value.every(comparableHistory);\n    if (!value || typeof value !== \"object\") return false;\n    const part = value as Record<string, unknown>;\n    if (part.type !== undefined && ![\"message\", \"text\", \"input_text\", \"output_text\", \"thinking\", \"redacted_thinking\", \"reasoning\", \"tool_use\", \"tool_result\", \"function_call\", \"function_call_output\"].includes(String(part.type))) return false;\n    if (part.type === \"tool_use\" || part.type === \"function_call\") return true;\n    // #4266: thinking-family blocks project to a named reasoning message and\n    // every wire hashes their bytes into that message's text — anthropicToCore\n    // reads b.thinking, openaiToCore carries reasoning_content, responsesToCore\n    // takes reasoning-item content (or a canonical opaque seed when only\n    // encrypted content is present) — so they are comparable by view. A\n    // payload-less thinking block carries nothing to compare, so it stays\n    // non-comparable (fail-closed: such a session refuses the fork instead of\n    // hashing a view with an unknowable content surface).\n    if (part.type === \"thinking\") return typeof part.thinking === \"string\" || typeof part.signature === \"string\";\n    if (part.type === \"redacted_thinking\") return typeof part.data === \"string\";\n    if (part.type === \"reasoning\") return true;\n    if (part.audio !== undefined && part.audio !== null) return false;\n    if (part.content !== undefined) return comparableHistory(part.content);\n    if (part.output !== undefined) return comparableHistory(part.output);\n    if (part.parts !== undefined) return comparableHistory(part.parts);\n    return typeof part.text === \"string\" || Array.isArray(part.tool_calls);\n}\ntype ForkRequest = {\n    protocolVersion: 1 | 2;\n    parentConversationId: string;\n    childConversationId: string;\n    parentRevision: string;\n    branchPoint: { messageCount: number; orderHash: string };\n    orderedMessages: ForkIdentity[];\n    idempotencyKey: string;\n};\n\nfunction stableJson(value: unknown): string {\n    if (Array.isArray(value)) return `[${value.map(stableJson).join(\",\")}]`;\n    if (value !== null && typeof value === \"object\") {\n        const obj = value as Record<string, unknown>;\n        return `{${Object.keys(obj).filter((k) => obj[k] !== undefined).sort().map((k) => `${JSON.stringify(k)}:${stableJson(obj[k])}`).join(\",\")}}`;\n    }\n    return JSON.stringify(value) ?? \"null\";\n}\n\nfunction forkHash(value: unknown): string {\n    return createHash(\"sha256\").update(stableJson(value), \"utf8\").digest(\"hex\");\n}\n\nfunction forkOrderHash(messages: ForkIdentity[]): string {\n    return createHash(\"sha256\").update(JSON.stringify(messages), \"utf8\").digest(\"hex\");\n}\n\nfunction forkToolIsError(message: CoreMessage): boolean {\n    return (message as CoreMessage & { toolIsError?: boolean }).toolIsError === true;\n}\n\n// Fork identity digests ONLY fields present on BOTH sides of the comparison:\n// the parent snapshot cells AND the child's replayed bytes re-projected at\n// ingress. thinkingTokens is deliberately EXCLUDED — the host projects it onto\n// prepared arrays (projectThinkingMass) and it never exists in the client's\n// bytes, so digesting it flags every stamped cell as spurious drift (the\n// GENERATED_METERING_FIELDS doctrine). Signed thinking content IS identity:\n// its carrier rides thinkingSignature / googleThoughtSignature, so a rotated\n// signature reads as drift (advisory adoption, one unfolded request) instead\n// of silently inheriting stale signature bytes (#1960 territory). The opaque\n// redacted_thinking payload is payload-addressed like images (#3751): its\n// projected text is a constant label carrying no bytes, so without this slot\n// a rotated payload under an unchanged id would pass the gate and inherit\n// stale bytes silently — the raw block's data digests into the tuple instead.\nfunction redactedPayloadDigest(message: CoreMessage): string | null {\n    const block = (message as CoreMessage & { rawAnthropicBlock?: { type?: unknown; data?: unknown } }).rawAnthropicBlock;\n    if (!block || block.type !== \"redacted_thinking\" || typeof block.data !== \"string\") return null;\n    return createHash(\"sha256\").update(block.data, \"utf8\").digest(\"hex\").slice(0, 16);\n}\n\nexport function forkMessageIdentityHash(message: CoreMessage): string {\n    const m = message as CoreMessage & { thinkingSignature?: string; googleThoughtSignature?: string };\n    return forkHash([m.role, m.contentType, m.text ?? null, m.toolName ?? null, m.toolCallId ?? null, m.thinkingSignature ?? null, m.googleThoughtSignature ?? null, m.summaryOfBlockId ?? null, forkToolIsError(m), redactedPayloadDigest(m)]);\n}\n\n/** #2077 CoW view equality for rememberPluginMessages' prefix walk: compares\n *  exactly the field set forkMessageIdentityHash digests, plus id. An id\n *  prefix match alone would keep a stale snapshot when a resent history flips\n *  an adapter-attached flag (toolIsError) under unchanged ids — the snapshot\n *  must track every byte fork matching can see. If an adapter ever attaches a\n *  new runtime field, it MUST be added here and to forkMessageIdentityHash\n *  together. */\n// thinkingTokens compares PRESENCE only (see forkMessageIdentityHash: the\n// value itself is one-sided metering noise, re-derived every turn — comparing\n// it would stop the CoW walk at every stamped cell and replace the whole\n// snapshot view on each turn). Presence is view-relevant: a freshly stamped\n// cell must displace an unstamped stored copy (or vice versa when attribution\n// ends), otherwise the stored snapshot silently loses — or keeps — the hidden\n// mass marker.\nfunction sameSnapshotView(a: CoreMessage, b: CoreMessage): boolean {\n    const am = a as CoreMessage & { thinkingSignature?: string; googleThoughtSignature?: string };\n    const bm = b as CoreMessage & { thinkingSignature?: string; googleThoughtSignature?: string };\n    return a.id === b.id && a.role === b.role && a.contentType === b.contentType\n        && a.text === b.text && a.toolName === b.toolName && a.toolCallId === b.toolCallId\n        && am.thinkingSignature === bm.thinkingSignature && am.googleThoughtSignature === bm.googleThoughtSignature\n        && (typeof a.thinkingTokens === \"number\") === (typeof b.thinkingTokens === \"number\")\n        && a.summaryOfBlockId === b.summaryOfBlockId\n        && forkToolIsError(a) === forkToolIsError(b);\n}\n\n/** #3741: classified verdict of the first-request inherited-prefix gate.\n *  `reason` is a stable failure class plus minimal evidence — safe to log and\n *  echo to the client (truncated ids/hashes only, never message content).\n *  Each evidence part appears only when ITS OWN check failed — a cell whose ref\n *  mapping was pruned (id+hash intact) reports ref-broken alone, not drift. */\ntype PublicForkPrefixVerdict = { ok: true } | { ok: false; reason: string };\n\nconst FORK_PREFIX_ID_PREVIEW = 16;\nconst FORK_PREFIX_HASH_PREVIEW = 12;\n\nfunction forkPrefixPreview(value: string): string {\n    return value.length > 0 ? value.slice(0, FORK_PREFIX_ID_PREVIEW) : \"-\";\n}\n\n/** Read under the session lock; compare ordered semantics, never just an id set.\n *  #3741: returns a classified verdict instead of a bare boolean — the 409 path\n *  was a total diagnostic blind spot. The classes separate the three drift\n *  shapes that matter for triage: id-drift (re-minted/renormalized history —\n *  version skew or host body rewrite), hash-drift-under-same-id (adapter-attached\n *  flags like toolIsError flipped under unchanged bytes), and structural shape\n *  changes (shorter replay, unmappable body). Any unexpected error stays\n *  fail-closed exactly as before. */\nexport function publicForkInputCheck(session: Session, protocol: WireProtocol, parsed: unknown): PublicForkPrefixVerdict {\n    const prefix = session.pluginSnapshot;\n    if (session.metadata.publicForkReceipt === undefined) return { ok: false, reason: \"receipt-missing\" };\n    if (!prefix) return { ok: false, reason: \"snapshot-missing\" };\n    try {\n        const incoming = incomingCoreMessages(protocol, parsed);\n        if (incoming === null) return { ok: false, reason: `incoming-unmappable (protocol=${protocol})` };\n        if (incoming.length < prefix.length) return { ok: false, reason: `prefix-longer-than-incoming (expected=${prefix.length} incoming=${incoming.length})` };\n        for (let index = 0; index < prefix.length; index += 1) {\n            const expected = prefix[index]!;\n            const candidate = incoming[index]!;\n            const ref = session.state.messageRefs.byRaw[expected.id];\n            // #2620: protected tool calls/results carry the kernel BLOCKED sentinel (no numeric\n            // ref, byRef never holds it) — a legitimate state, not a broken mapping.\n            const refOk = ref !== undefined && (ref === BLOCKED_REF || session.state.messageRefs.byRef[ref] === expected.id);\n            const idOk = candidate.id === expected.id;\n            const expectedHash = forkMessageIdentityHash(expected);\n            const candidateHash = forkMessageIdentityHash(candidate);\n            if (!refOk || !idOk || candidateHash !== expectedHash) {\n                const parts = [`cell-mismatch@${index}`];\n                if (!refOk) parts.push(`ref-broken (rawId=${forkPrefixPreview(expected.id)} ref=${ref ?? \"MISSING\"})`);\n                if (!idOk) parts.push(`id-drift expected=${forkPrefixPreview(expected.id)} got=${forkPrefixPreview(candidate.id)}`);\n                else if (candidateHash !== expectedHash) parts.push(`hash-drift-under-same-id role=${candidate.role} expected-hash=${expectedHash.slice(0, FORK_PREFIX_HASH_PREVIEW)} got-hash=${candidateHash.slice(0, FORK_PREFIX_HASH_PREVIEW)}`);\n                return { ok: false, reason: parts.join(\" \") };\n            }\n        }\n        return { ok: true };\n    } catch (err) {\n        return { ok: false, reason: `projection-error (${err instanceof Error ? err.message : String(err)})` };\n    }\n}\n\n/** Cheap, cache-backed read of the fork parentRevision. forkSnapshot() is a\n *  pure function of the session content and status polling would otherwise\n *  re-hash the entire history (plus the CCR store, payload by payload) on\n *  every call (#2017 review item E); revisionEpoch — bumped by markDirty on\n *  every mutation — keys the cache, so an unchanged session costs O(1).\n *  Same fail-closed errors as forkSnapshot itself propagate to the caller. */\nfunction sessionRevisionOf(session: Session): string {\n    const epoch = session.revisionEpoch ?? 0;\n    const cache = session.pluginRevisionCache;\n    if (cache && cache.epoch === epoch) return cache.revision;\n    const revision = forkSnapshot(session).parentRevision;\n    session.pluginRevisionCache = { epoch, revision };\n    return revision;\n}\n\n/** #5140 item 4: a non-retained parent cold-restored in shadow mode loses its\n *  resident pluginSnapshot (persist.ts retention gate) even though index.db\n *  still holds the independently recorded unfolded raw tail. Rebuild that tail\n *  through its LOGICAL tailSeqs projection (never append-log order, never the\n *  folded envelope) and prove it IS this session's complete ordered history\n *  before it may stand in for the snapshot: every seq resolves (zero gaps), ids\n *  equal state.lastPassIds in exact order, and it sits under the UTF-8 byte cap.\n *  Pure — never mutates the session. Any miss returns null so callers fail\n *  closed exactly as before. */\n// #5140 CI-red follow-up: every reconstruction miss records WHICH gate fired,\n// so a 409 SNAPSHOT_UNAVAILABLE is diagnosable from server logs and the\n// client-visible error instead of being one silent null among five.\nconst reconMissGate = new Map<string, { gate: string; at: number }>();\nconst reconMissLastLogMs = new Map<string, number>();\n\nfunction reconMiss(session: Session, gate: string, detail?: string): null {\n    const why = detail ? `${gate} ${detail}` : gate;\n    const key = `${session.id}:${gate}`;\n    const now = Date.now();\n    if (now - (reconMissLastLogMs.get(key) ?? 0) >= 10_000) {\n        reconMissLastLogMs.set(key, now);\n        loggerLog(\"warn\", `[plugin] raw-tail reconstruction unavailable for ${session.id} (${why}) — snapshot/fork falls back to the legacy path`);\n    }\n    reconMissGate.set(session.id, { gate: why, at: now });\n    return null;\n}\n\nfunction reconMissReason(sessionId: string): string | undefined {\n    const hit = reconMissGate.get(sessionId);\n    return hit && Date.now() - hit.at < 30_000 ? hit.gate : undefined;\n}\n\n// #5188 round 3: #5140's flake was a timing race — the ctor's first sidecar open\n// died on a transient disk spike under shard load, the resource cleared\n// milliseconds later, and the cold-restore snapshot request arrived before any\n// post-spike recovery attempt had fired. When reconstruction is actually needed\n// and the sidecar is merely MISSING (recoverable without restart), the two\n// user-visible 409 paths wait a bounded moment for that self-recovery instead\n// of racing it. Latched-disabled never waits — waiting cannot help there. The\n// pre-lock read of pluginSnapshot/lastPassIds is fine for gating: a stale answer\n// only costs one unnecessary wait or skips one (same immediate 409 as before).\nasync function waitForReconstructionReplicas(session: Session): Promise<void> {\n    if (session.pluginSnapshot !== undefined) return;\n    const expected = session.state.lastPassIds;\n    if (!expected || expected.length === 0) return;\n    const store = getStore();\n    if (store.replicasAvailable()) return;\n    if (store.sidecarDownReason() !== \"sidecar-missing\") return;\n    await store.waitForReplicas();\n}\n\nfunction reconstructRawTailForFork(session: Session): CoreMessage[] | null {\n    const expected = session.state.lastPassIds;\n    if (!expected || expected.length === 0) return reconMiss(session, \"empty-lastPassIds\");\n    const store = getStore();\n    if (!store.replicasAvailable()) return reconMiss(session, \"replicasUnavailable\", store.sidecarDownReason());\n    const seqs = store.unifiedTailSeqs(session.id);\n    if (!seqs || seqs.length === 0) return reconMiss(session, \"empty-tailSeqs\", `expected=${expected.length}`);\n    const rows = store.unifiedTailViewRows(session.id);\n    if (!rows) return reconMiss(session, \"null-tailViewRows\", `seqs=${seqs.length}`);\n    const bySeq = new Map<number, string>();\n    for (const row of rows) bySeq.set(row.seq, row.content);\n    const out: CoreMessage[] = [];\n    for (const seq of seqs) {\n        const content = bySeq.get(seq);\n        if (content === undefined) return reconMiss(session, \"gap-tailRow\", `seq=${seq}/${seqs.length} rows=${rows.length}`); // gap: a logical seq has no stored row\n        let msg: CoreMessage;\n        try { msg = JSON.parse(content) as CoreMessage; } catch { return reconMiss(session, \"unparseable-row\", `seq=${seq}`); }\n        if (typeof msg.id !== \"string\" || typeof msg.role !== \"string\") return reconMiss(session, \"bad-row-shape\", `seq=${seq}`);\n        out.push(msg);\n    }\n    if (out.length !== expected.length) return reconMiss(session, \"length-mismatch\", `rows=${out.length} expected=${expected.length}`);\n    for (let i = 0; i < out.length; i += 1) if (out[i]!.id !== expected[i]) return reconMiss(session, \"id-mismatch\", `index=${i}`);\n    const cap = publicSnapshotCapBytes();\n    if (Buffer.byteLength(stableJson(out), \"utf8\") > cap) return reconMiss(session, \"cap-exceeded\");\n    reconMissGate.delete(session.id);\n    return out;\n}\n\nfunction forkSnapshot(session: Session, source?: CoreMessage[] | null) {\n    const messages = source ?? session.pluginSnapshot ?? reconstructRawTailForFork(session);\n    if (!messages) {\n        const capped = session.metadata.publicSnapshotCapped === true;\n        const base = capped ? \"raw snapshot exceeded the retention cap (BILI_PUBLIC_SNAPSHOT_CAP_BYTES); fork is refused rather than retaining an unbounded raw copy\" : \"raw snapshot unavailable; send a fresh plugin model request\";\n        // the capped base names the refusal itself; a gate recorded under it is\n        // incidental (reconstruction may bail before reaching the cap check)\n        const why = capped ? undefined : reconMissReason(session.id);\n        throw new Error(why ? `${base} [reconstruction: ${why}]` : base);\n    }\n    // #4266 mechanism 1: signed thinking is no longer an opaque refusal. Wire\n    // thinking/redacted_thinking blocks project to a named reasoning message\n    // (anthropicToCore), so they are comparable by view. The host-projected\n    // metering mass (thinkingTokens, cache-ledger GENERATED_METERING_FIELDS)\n    // stays OUT of fork identity: it exists only on prepared arrays, never in\n    // the client's bytes, and is re-derived every turn — digesting it would\n    // flag every stamped cell as spurious drift on the child's first request.\n    // Signed content rides thinkingSignature/googleThoughtSignature inside the\n    // identity hash, so only genuinely uncomparable content (images, audio,\n    // publicSnapshotTextComparable === false) still refuses.\n    if (session.metadata.publicSnapshotTextComparable === false) throw new Error(\"multimodal or opaque content cannot be compared by text\");\n    const store = contentStoreOf(session);\n    const expectedStoredRefs = session.metadata.publicSnapshotStoredRefs;\n    if (Array.isArray(expectedStoredRefs) && expectedStoredRefs.some((ref) => typeof ref !== \"string\" || !store.byRef[ref])) throw new Error(\"CCR original index unavailable\");\n    const indexedHashes = new Set(Object.values(store.byRef).map((entry) => entry.hash));\n    if (Object.entries(store.byHash).some(([hash, text]) => !indexedHashes.has(hash) || typeof text !== \"string\" || createHash(\"sha256\").update(text, \"utf8\").digest(\"hex\") !== hash)) throw new Error(\"CCR original payload/index inconsistent\");\n    if (Object.entries(store.byRef).some(([ref, entry]) => typeof store.byHash[entry.hash] !== \"string\" || (session.state.messageRefs.byRaw[entry.rawId] !== undefined && (session.state.messageRefs.byRaw[entry.rawId] !== ref || session.state.messageRefs.byRef[ref] !== entry.rawId)))) throw new Error(\"CCR original alias inconsistent\");\n    const orderedMessages = messages.map((m, i): ForkIdentity => {\n        const ref = session.state.messageRefs.byRaw[m.id];\n        // #2620: protected tool calls/results map to the kernel BLOCKED sentinel by design\n        // (kernel assignRefs) — no numeric ref exists and byRef never holds it, so the\n        // bidirectional check applies only to numeric refs; genuine corruption still fails.\n        // #2676: name the offending message in the error — a bare invariant string gave no\n        // clue which of hundreds of snapshot entries broke the mapping.\n        if (!ref || (ref !== BLOCKED_REF && session.state.messageRefs.byRef[ref] !== m.id)) throw new Error(`raw/ref mapping inconsistent (msg ${i + 1}/${messages.length} role=${m.role} tool=${m.toolName ?? \"-\"} ref=${ref ?? \"MISSING\"} rawId=${m.id.slice(0, 16)})`);\n        const entry = store.byRef[ref];\n        const placeholder = m.text ? parseStoredPlaceholder(m.text) : null;\n        if ((entry && (entry.rawId !== m.id || typeof store.byHash[entry.hash] !== \"string\")) || (placeholder && (placeholder.ref !== ref || !entry))) throw new Error(\"CCR original unavailable or alias inconsistent\");\n        return { rawId: m.id, ref: ref === BLOCKED_REF ? null : ref, identityHash: forkMessageIdentityHash(m) };\n    });\n    // #2671 Phase 2b (fork protocol v2): the revision token is now\n    // {sessionId, seq, active block set} — stable across any churn that does\n    // not move the ordered snapshot or the active blocks (v1 hashed the whole\n    // state incl. every CCR payload, so unrelated store activity flipped it;\n    // see forkParentRevisionLegacy). The deep fork checks (orderHash +\n    // byte-exact prefix comparison below) remain the correctness boundary;\n    // the revision is only the cheap early-exit token.\n    const activeBlockSet = session.state.blocks.filter((b) => b.active).map((b) => b.blockId).sort();\n    const parentRevision = forkHash({ sessionId: session.id, seq: orderedMessages.length, blockSet: activeBlockSet });\n    return { protocolVersion: 2, status: \"exact\", sessionId: session.id, parentRevision, orderHash: forkOrderHash(orderedMessages), orderedMessages, messages: messages.map((m, i) => ({ rawId: m.id, ref: orderedMessages[i]!.ref, role: m.role, text: m.text, toolName: m.toolName, toolCallId: m.toolCallId, contentType: m.contentType, toolIsError: forkToolIsError(m) })) };\n}\n\n/** #2671 Phase 2b transition digest: fork protocol v1 hashed the ENTIRE\n *  snapshot ({sessionId, messages, state, blockContents, contentStore}) so\n *  any unrelated store churn (post-snapshot CCR activity, stats nudges,\n *  image-restore rewrites) flipped parentRevision and forced spurious 409s.\n *  v2 hashes only {sessionId, seq, active block set}. The POST handler still\n *  ACCEPTS a v1 hash for one transition version (clients that snapshotted\n *  under an older proxy); this legacy digest is recomputed ONLY on that\n *  fallback path — GET snapshot and status polling never pay O(store)\n *  hashing. Drop this (and the fallback) once no v1 client can exist. */\nexport function forkParentRevisionLegacy(session: Session): string {\n    const messages = session.pluginSnapshot;\n    if (!messages) throw new Error(\"raw snapshot unavailable\");\n    const store = contentStoreOf(session);\n    const state = { ...session.state };\n    return forkHash({ sessionId: session.id, messages, state, blockContents: Object.fromEntries(session.blockContents), contentStore: store });\n}\n\n// #4942: async — on network storage backends the existence probes must be\n// able to reach the DB (the sync facade misses by design there). Materialization\n// must ride the SAME async seam: a sync getSession after an async probe would\n// mint an EMPTY resident ghost for a DB-only id, and that ghost then poisons\n// every later getSessionAsync of the id for the process lifetime.\nasync function resolveForkConversation(id: string): Promise<Session | undefined> {\n    if (peekSession(id)) return peekSession(id);\n    if (await getStore().loadAsync(id)) return getSessionAsync(id);\n    const { session, entry } = resolveConversation(id);\n    if (session) return session;\n    const persistedId = entry?.sessionId ?? id;\n    if (!(await getStore().loadAsync(persistedId))) return undefined;\n    return getSessionAsync(persistedId);\n}\n\n/** #2601 freshness window for persona-lineage following — same family as\n *  SPLIT_CANARY_FRESH_MS (splitSessionWarnings): a fork that has not carried\n *  traffic for this long is not \"live\" anymore and the parent id routes home. */\nconst PERSONA_LINEAGE_FRESH_MS = 10 * 60 * 1000;\n\n/** #2948: does the session hold usable refs? A `|sub:` descendant that never\n *  rendered a message holds none — the aux/side-lane shape: dsh auto-review\n *  blobs fork onto their own lane and carry perpetual traffic (stats.requests\n *  bumped, kernel state untouched / turns failing mid-prepare), so they look\n *  \"live\" under every freshness criterion yet can serve NOTHING a management\n *  call needs. Every compress/decompress/acp_status routed there fails\n *  \"every ref is unknown to this session\" (the #2948 breaker), so such a lane\n *  can never be a lineage-follow target. byRef is the sharp test: blocked\n *  entries live in byRaw only and are unusable anyway. */\nfunction holdsRefs(s: Session): boolean {\n    return Object.keys(s.state.messageRefs?.byRef ?? {}).length > 0;\n}\n\n/** #2601: persona-fork descendants of a raw host id — sessions minted by the\n *  persona-anchor fork branch (`${rawId}|sub:${fp}`, persona-anchor.ts) that\n *  actually carried traffic, are fresh, AND hold refs (#2948: freshness alone\n *  selected ref-less aux lanes — see holdsRefs). Grouping by\n *  `id.split(\"|sub:\")[0]` is the house idiom (splitSessionWarnings, #2170\n *  canary). Sorted by lastSeen descending (listSessions order). */\nfunction personaDescendantsOf(baseId: string): Session[] {\n    if (baseId.includes(\"|sub:\")) return [];\n    const prefix = `${baseId}|sub:`;\n    const now = Date.now();\n    return listSessions().filter((s) => s.id.startsWith(prefix) && (s.stats?.requests ?? 0) > 0 && now - (s.lastSeen ?? 0) <= PERSONA_LINEAGE_FRESH_MS && holdsRefs(s));\n}\n\n/** #3397: highest ref number cited anywhere in the tool arguments\n *  (`mNNNNN`, the kernel's ref format) — recursive string walk. 0 = none. */\nfunction maxCitedRefNum(args: Record<string, unknown>): number {\n    let max = 0;\n    const visit = (v: unknown): void => {\n        if (typeof v === \"string\") {\n            for (const m of v.matchAll(/\\bm(\\d{5,})\\b/g)) max = Math.max(max, Number(m[1]));\n        } else if (Array.isArray(v)) {\n            for (const item of v) visit(item);\n        } else if (v !== null && typeof v === \"object\") {\n            for (const item of Object.values(v as Record<string, unknown>)) visit(item);\n        }\n    };\n    visit(args);\n    return max;\n}\n\n/** #3397: highest ref this session ever minted — byRef only grows (kernel\n *  id-never-reused contract), so a fork whose frontier sits below a cited\n *  ref cannot hold it. Same shape as stream.ts beyondFrontierNote. */\nfunction highestMintedRefNum(s: Session): number {\n    let max = 0;\n    for (const ref of Object.keys(s.state.messageRefs?.byRef ?? {})) {\n        const m = /^m(\\d{5,})$/.exec(ref);\n        if (m) max = Math.max(max, Number(m[1]));\n    }\n    return max;\n}\n\n/** #2601: the lineage's live session when the host-stamped RAW parent went\n *  FROZEN before the fork was born — the fork is that parent's continuation,\n *  and the host's compress/decompress/acp_status forwards (which keep\n *  stamping the raw id, because dsh cannot know bili derived a `|sub:` key)\n *  must follow it or strand on refs the frozen parent no longer holds — the\n *  #2601 \"every ref is unknown to this session\" breaker. The discriminator\n *  is BIRTH ORDER, not freshness: `fork.createdAt > parent.lastSeen` means\n *  the parent saw NO traffic after the fork was minted (frozen), so the\n *  fork's namespace is the only one the host's refs can live in. A parent\n *  that kept receiving turns after the fork was created (parallel persona\n *  forks / subagent lanes sharing the base id) stays authoritative — it is\n *  live, ITS namespace holds the refs, and re-routing the host's calls into\n *  a fork's namespace reproduces the same breaker in reverse (the dsh\n *  fusion-board incident: 8× cannot-anchor after the redirect; the\n *  pre-fix `fork.lastSeen > parent.lastSeen` rule also matches this shape —\n *  a still-active parent with a merely fresher parallel fork). Undefined\n *  when the parent is still the live session (switch back to the raw\n *  persona self-heals: the parent's lastSeen lands strictly after the\n *  fork's createdAt) or when no descendant holds refs (#2948: a ref-less\n *  aux lane is not a target — following it reproduces the same breaker it\n *  exists to cure; candidates are filtered in personaDescendantsOf, so a\n *  ref-holding sibling still wins over a fresher ref-less one).\n *  #3397: several forks can be live at once — dsh's chatty sidecar persona\n *  fires every few seconds while the owner conversation idles, so raw\n *  recency picked the WRONG fork and the call died on its small ref space\n *  (\"every ref is unknown\"). When the arguments cite refs, prefer a fork\n *  whose minted ref space can contain them (frontier ≥ max cited); with no\n *  fit or no citation the pick falls back to recency — identical to the\n *  pre-fix behavior, never worse. (#3647: the candidate filter below is\n *  birth-order — see the head of this comment.) */\nfunction livePersonaDescendant(parent: Session, maxCited?: number): Session | undefined {\n    if (parent.id.includes(\"|sub:\")) return undefined;\n    const cands = personaDescendantsOf(parent.id).filter((s) => (s.createdAt ?? 0) > (parent.lastSeen ?? 0));\n    if (cands.length === 0) return undefined;\n    const cited = maxCited ?? 0;\n    if (cited > 0) {\n        const fits = cands.filter((s) => highestMintedRefNum(s) >= cited);\n        if (fits.length > 0) return fits[0]; // listSessions order = lastSeen desc\n    }\n    return cands[0];\n}\n\n/** #2601: pick the witness session when it is a fresh `|sub:` fork of the\n *  stale parent — the #2601 incident shape: the host-stamped native caller\n *  (raw id) conflicts with the outbound witness because the tool call was\n *  minted in the fork's ref space. A lineage witness is not a spoof; a\n *  FOREIGN witness keeps the #2024 rules (refusal / native-caller override).\n *  Also follows when the caller itself is a fork whose parent minted the\n *  call (witness = base session) — same lineage, base of the same root. */\nfunction personaLineageWitness(witnessIds: Set<string>, resolvedId: string): Session | undefined {\n    const base = resolvedId.split(\"|sub:\")[0]!;\n    for (const w of witnessIds) {\n        if (w === resolvedId) continue;\n        if (!w.includes(\"|sub:\") && w !== base) continue; // witness must be in the same lineage root\n        if (w.includes(\"|sub:\") && w.split(\"|sub:\")[0] !== base) continue;\n        const s = peekSession(w);\n        if (s && (s.stats?.requests ?? 0) > 0 && Date.now() - (s.lastSeen ?? 0) <= PERSONA_LINEAGE_FRESH_MS) return s;\n    }\n    return undefined;\n}\n\nfunction forkReply(res: ServerResponse, status: number, body: unknown): void {\n    res.writeHead(status, { \"content-type\": \"application/json\" });\n    res.end(JSON.stringify(body));\n}\n\nexport async function handlePluginSnapshot(conversationId: string, res: ServerResponse): Promise<void> {\n    if (!conversationId) return forkReply(res, 400, { ok: false, code: \"INVALID_REQUEST\", error: \"conversationId is required\" });\n    const session = await resolveForkConversation(conversationId);\n    if (!session) return forkReply(res, 404, { ok: false, code: \"PARENT_NOT_FOUND\", error: \"unknown plugin conversation\" });\n    acquireInFlight(session);\n    try {\n        await waitForReconstructionReplicas(session); // #5188 round 3: don't race self-recovery into a 409\n        await withSessionLock(session, () => forkReply(res, 200, { ok: true, conversationId, ...forkSnapshot(session) }));\n    } catch (err) {\n        forkReply(res, 409, { ok: false, status: \"unavailable\", code: \"SNAPSHOT_UNAVAILABLE\", error: String(err) });\n    } finally {\n        releaseInFlight(session);\n    }\n}\n\nfunction parseForkRequest(payload: string): ForkRequest {\n    const value: unknown = JSON.parse(payload);\n    if (!value || typeof value !== \"object\" || Array.isArray(value)) throw new Error(\"expected fork object\");\n    const b = value as Record<string, unknown>;\n    const identifier = (v: unknown): v is string => typeof v === \"string\" && v.length > 0 && v.length <= 256 && v.trim() === v && !/[\\x00-\\x1f\\x7f]/.test(v);\n    const hash = (v: unknown): v is string => typeof v === \"string\" && /^[a-f0-9]{64}$/.test(v);\n    if (b.protocolVersion !== 1 && b.protocolVersion !== 2) throw new Error(\"unsupported fork protocolVersion (expected 1 or 2)\");\n    if (!identifier(b.parentConversationId) || !identifier(b.childConversationId) || !identifier(b.idempotencyKey) || !hash(b.parentRevision)) throw new Error(\"invalid fork identity/revision\");\n    if (b.parentConversationId === b.childConversationId) throw new Error(\"parent and child must differ\");\n    const point = b.branchPoint as Record<string, unknown> | null;\n    if (!point || !Number.isSafeInteger(point.messageCount) || (point.messageCount as number) < 0 || !hash(point.orderHash) || !Array.isArray(b.orderedMessages) || b.orderedMessages.length !== point.messageCount) throw new Error(\"invalid branchPoint/orderedMessages\");\n    const orderedMessages = b.orderedMessages.map((v: unknown): ForkIdentity => {\n        if (!v || typeof v !== \"object\") throw new Error(\"invalid ordered identity\");\n        const item = v as Record<string, unknown>;\n        // #2620: ref null = intentionally unaddressable (kernel-protected) prefix message.\n        if (!identifier(item.rawId) || !(item.ref === null || (typeof item.ref === \"string\" && /^m\\d{5,}$/.test(item.ref))) || !hash(item.identityHash)) throw new Error(\"invalid raw/ref identity\");\n        return { rawId: item.rawId, ref: item.ref, identityHash: item.identityHash };\n    });\n    return { protocolVersion: b.protocolVersion, parentConversationId: b.parentConversationId, childConversationId: b.childConversationId, parentRevision: b.parentRevision, branchPoint: { messageCount: point.messageCount as number, orderHash: point.orderHash }, orderedMessages, idempotencyKey: b.idempotencyKey };\n}\n\n/** [#2399 stage 2] omp/pi identity-register their session ids at session_start\n *  — BEFORE a fork child's first model request can trigger the extension-side\n *  adoption — so a fork POST for such a child arrives with the id already in\n *  registeredIds. That register carries the SAME parent the fork request\n *  declares, so it is a compatible lineage claim by the same host, not a rival\n *  child: allow the fork through and drop the register entry on success (the\n *  fork-created conversation then binds by the conversations map, exactly like\n *  a dsh-style child that never registered). A registered id WITHOUT a parent\n *  declaration, or with a different parent, stays a conflict. */\nfunction forkChildHeldBySameParent(child: string, parent: string): boolean {\n    return registeredIds.get(child)?.parentConversationId === parent;\n}\n\nexport async function handlePluginFork(payload: string, res: ServerResponse): Promise<void> {\n    let request: ForkRequest;\n    try { request = parseForkRequest(payload); }\n    catch (err) { return forkReply(res, 400, { ok: false, code: \"INVALID_REQUEST\", error: String(err) }); }\n    const requestHash = forkHash(request);\n    const replay = async (): Promise<boolean> => {\n        await getStore().recoverCompletedFork(request.childConversationId);\n        const existing = await resolveForkConversation(request.childConversationId);\n        if (!existing) return false;\n        const receipt = existing.metadata.publicForkReceipt as { requestHash?: unknown; response?: unknown } | undefined;\n        if (receipt?.requestHash === requestHash) forkReply(res, 200, { ...(receipt.response as Record<string, unknown>), replayed: true });\n        else forkReply(res, 409, { ok: false, code: \"CHILD_CONFLICT\", error: \"child conversation already exists or idempotency payload differs\" });\n        return true;\n    };\n    try { if (await replay()) return; }\n    catch (err) { return forkReply(res, 503, { ok: false, status: \"unavailable\", code: \"FORK_FAILED\", error: String(err) }); }\n    if (conversations.has(request.childConversationId) || pendingRegisters.some((r) => r.conversationId === request.childConversationId) || (registeredIds.has(request.childConversationId) && !forkChildHeldBySameParent(request.childConversationId, request.parentConversationId))) return forkReply(res, 409, { ok: false, code: \"CHILD_CONFLICT\", error: \"child conversation already registered\" });\n    const parent = await resolveForkConversation(request.parentConversationId);\n    if (!parent) return forkReply(res, 404, { ok: false, code: \"PARENT_NOT_FOUND\", error: \"parent conversation not found\" });\n    acquireInFlight(parent);\n    try {\n        await waitForReconstructionReplicas(parent); // #5188 round 3: don't race self-recovery into a 409\n        // #4911: async callback — the unified row clone below awaits the\n        // backend on network backends; withSessionLock accepts () => T |\n        // Promise<T>, so the lock scope and ordering are unchanged.\n        await withSessionLock(parent, async () => {\n            if (await replay()) return;\n            if (conversations.has(request.childConversationId) || pendingRegisters.some((r) => r.conversationId === request.childConversationId) || (registeredIds.has(request.childConversationId) && !forkChildHeldBySameParent(request.childConversationId, request.parentConversationId))) return forkReply(res, 409, { ok: false, code: \"CHILD_CONFLICT\", error: \"child conversation already registered\" });\n            // #5140 item 4: a cold non-retained parent has no resident snapshot;\n            // stand in with the verified unified raw tail (no fresh model call).\n            const source = parent.pluginSnapshot ?? reconstructRawTailForFork(parent);\n            let snapshot: ReturnType<typeof forkSnapshot>;\n            try { snapshot = forkSnapshot(parent, source); }\n            catch (err) { return forkReply(res, 409, { ok: false, status: \"unavailable\", code: \"SNAPSHOT_UNAVAILABLE\", error: String(err) }); }\n            if (snapshot.parentRevision !== request.parentRevision) {\n                // #2671 Phase 2b: accept a stale v1 revision (whole-store hash) from\n                // clients that snapshotted under an older proxy — one transition\n                // version, then the mismatch is a real conflict.\n                let legacy: string | null = null;\n                try { legacy = forkParentRevisionLegacy(parent); } catch { legacy = null; }\n                if (legacy !== request.parentRevision) return forkReply(res, 409, { ok: false, code: \"PARENT_REVISION_CONFLICT\", error: \"parent revision changed\" });\n            }\n            const prefix = snapshot.orderedMessages.slice(0, request.branchPoint.messageCount);\n            if (prefix.length !== request.branchPoint.messageCount || forkOrderHash(request.orderedMessages) !== request.branchPoint.orderHash || stableJson(prefix) !== stableJson(request.orderedMessages)) return forkReply(res, 409, { ok: false, code: \"BRANCH_POINT_CONFLICT\", error: \"ordered prefix/hash does not match parent\" });\n            const rawIds = new Set(prefix.map((m) => m.rawId));\n            const child = createSession(request.childConversationId, { ...parent.meta, label: request.childConversationId });\n            const crossing = parent.state.blocks.filter((b) => b.effectiveMessageIds.some((id) => rawIds.has(id)) && !b.effectiveMessageIds.every((id) => rawIds.has(id)));\n            const blocks = parent.state.blocks.filter((b) => b.effectiveMessageIds.length > 0 && b.effectiveMessageIds.every((id) => rawIds.has(id)));\n            const blockIds = new Set(blocks.map((b) => b.blockId));\n            const expandedChildren = new Set(crossing.flatMap((b) => b.directBlockIds));\n            for (const b of [...blocks, ...crossing]) {\n                const content = parent.blockContents.get(b.blockId);\n                if (!content || !content.full || typeof content.full.text !== \"string\" || !content.full.text || b.directBlockIds.some((id) => !parent.state.blocks.some((childBlock) => childBlock.blockId === id))) return forkReply(res, 409, { ok: false, status: \"unavailable\", code: \"PARENT_STATE_INCOMPLETE\", error: \"nested block/original content unavailable\" });\n            }\n            for (const b of blocks) {\n                if (b.directBlockIds.some((id) => !blockIds.has(id))) return forkReply(res, 409, { ok: false, status: \"unavailable\", code: \"PARENT_STATE_INCOMPLETE\", error: \"nested block outside matched prefix\" });\n                child.state.blocks.push({ ...structuredClone(b), ...(expandedChildren.has(b.blockId) ? { active: false, expanded: true } : {}) });\n                child.blockContents.set(b.blockId, structuredClone(parent.blockContents.get(b.blockId)!));\n            }\n            // Keep the issued ref namespace reserved, including dead refs, to prevent reuse.\n            child.state.messageRefs = structuredClone(parent.state.messageRefs);\n            for (const { rawId, ref } of prefix) {\n                // #2620: ref null = intentionally unaddressable; keep the raw id reserved under\n                // the kernel sentinel exactly as the parent holds it. byRef/tokenSnapshot are\n                // numeric-ref spaces and never see the sentinel.\n                child.state.messageRefs.byRaw[rawId] = ref ?? BLOCKED_REF;\n                if (ref !== null) {\n                    child.state.messageRefs.byRef[ref] = rawId;\n                    if (parent.state.tokenSnapshot[ref] !== undefined) child.state.tokenSnapsh