  systemPromptTokens,\n            state: session.state,\n            nudge,\n            modelContextLimit,\n            // #1320: countMessageTokens includes host-projected thinking mass\n            // (signature-only blocks) on the same scale as the breakdown rows.\n            unprunedTokens: mem && mem.original.length > 0\n                ? mem.original.reduce((sum, m) => sum + countMessageTokens(m), 0) + systemPromptTokens\n                : undefined,\n        });\n    } catch {\n        panel = undefined;\n    }\n    // Human-only deep link. Deliberately inserted BEFORE the footer line: the LLM-context\n    // stripper (src/acp-panel.ts) anchors this box on its top border AND its\n    // \"Tag visibility\" footer — anything appended after the footer would break the whole\n    // message match and ship the panel into the model context.\n    // #1577: an active advisory must reach the one surface native/plugin-lane\n    // users actually see — the /acp panel — via the same before-footer slot the\n    // Web UI link uses (the footer anchors the LLM-context stripper).\n    const preFooter: string[] = [];\n    if (protectedMassLine !== undefined) {\n        preFooter.push(protectedMassLine);\n    }\n    const adv = getAdvisoryState();\n    if (adv.active) {\n        preFooter.push(`⚠️ CRITICAL ADVISORY: ${describeAdvisory(adv.active, adv.lastError)}`);\n    }\n    // #2904: no-ceiling degraded state set by restoreOutputBudget — surface it\n    // here because the only other signal is a once-per-model log warn invisible\n    // to GUI hosts (#1158). Marker is single-slot, last-model-wins; shown only for\n    // the active model, so a healthy value / model switch clears it automatically.\n    const obd = session.metadata.outputBudgetDegraded as { model?: string; value?: number; ts?: number } | undefined;\n    const lastModel = typeof session.metadata.lastModel === \"string\" ? session.metadata.lastModel : undefined;\n    if (obd !== undefined && obd.model !== undefined && obd.value !== undefined && obd.model === lastModel) {\n        preFooter.push(`⚠️ OUTPUT BUDGET: model \"${obd.model}\" has NO known output ceiling — outgoing max_tokens restored to ${obd.value} tokens from the client's own estimate (no ceiling to back it); longer replies may cut off at the output limit. Declare an output limit in bili config or set maxTokens on the host model item (#2904).`);\n    }\n    const upd = getUpdateVisibility(VERSION);\n    if (upd.visible) {\n        // #1870 visibility for the silent courier, #1977 display policy:\n        // silent unless the span carries a critical-tier entry — one line,\n        // same before-footer slot as the advisory (remote-doc text; the\n        // $-escape below already covers it).\n        preFooter.push(describeUpdateReady(upd));\n    }\n    const webUrl = webSessionUrl(deps.webOrigin, session.id);\n    if (webUrl !== undefined) {\n        preFooter.push(`Web UI: ${webUrl}`);\n    }\n    // #3719: latest-release pointer — sync cache read only, so the status path\n    // stays network-free and fast; the web endpoint (and the fire-and-forget\n    // refresh below) warm the cache. Fail silent: no line until a fetch lands.\n    const clLatest = latestChangelog();\n    if (clLatest !== undefined) {\n        preFooter.push(`changelog: ${clLatest.tag} ${clLatest.url}`);\n    } else {\n        warmChangelogOnce(); // once per process; never throws\n    }\n    // #4906: same fire-and-forget cadence as the changelog warm above — one\n    // GitHub-master blog pull when this process starts out COLD (no live\n    // master overlay yet); processes that already hold a master overlay keep\n    // the status path network-free. Internal guard; never throws.\n    warmBlogRefreshOnce();\n    if (panel !== undefined && preFooter.length > 0) {\n        // Escape $ so advisory text (remote doc content) cannot be read as\n        // replace() pattern syntax ($&, $\\`, $') and corrupt the box lines.\n        panel = panel.