nerate = () => {\n        if (!sawTerminal || res.destroyed || res.writableEnded) return;\n        const st = { inputChars: 0, outputChars: 0, dropped: false, dropCount: 0 };\n        for (const f of [textFilter, reasonFilter]) {\n            const s = f.stats();\n            st.inputChars += s.inputChars;\n            st.outputChars += s.outputChars;\n            st.dropped = st.dropped || s.dropped;\n            st.dropCount += s.dropCount;\n        }\n        const msg = degenerateTurnWarning({\n            reason: finalFinishReason,\n            terminalReason: \"stop\",\n            toolCalls: 0,\n            text: { inputChars: st.inputChars, outputChars: visibleTextChars, dropped: st.dropped, dropCount: st.dropCount },\n            sawThinking: false,\n            wire: \"plugin-passthrough-commandcode\",\n        });\n        if (msg) {\n            loggerLog(\"warn\", msg);\n            log?.(msg);\n        }\n    };\n    // Write back whatever prose the filters are still holding as synthetic\n    // lines of the ORIGINAL event type, so held tails land before the\n    // terminal frame instead of being silently dropped (mirrors the SSE\n    // pipe's flushTails-at-terminal pattern).\n    const flushFieldTails = async () => {\n        const textTail = textFilter.flush();\n        const reasonTail = reasonFilter.flush();\n        if (textTail.length > 0 && !res.destroyed && !res.writableEnded) {\n            visibleTextChars += textTail.length;\n            if (!res.write(Buffer.from(JSON.stringify({ type: \"text-delta\", text: textTail }) + \"\\n\", \"utf8\"))) await awaitDrain(res);\n        }\n        if (reasonTail.length > 0 && !res.destroyed && !res.writableEnded) {\n            if (!res.write(Buffer.from(JSON.stringify({ type: \"reasoning-delta\", text: reasonTail }) + \"\\n\", \"utf8\"))) await awaitDrain(res);\n        }\n    };\n    try {\n        while (true) {\n            let done: boolean;\n            let value: Uint8Array | undefined;\n            try {\n                ({ done, value } = await reader.read());\n            } catch (e) {\n                settleUsage();\n                if (res.destroyed || res.writableEnded) return;\n                try { await flushFieldTails(); } catch { /* client half-gone; the signal below is best-effort too */ }\n                loggerLog(\"warn\", `[plugin] upstream stream read failed (commandcode): ${String(e instanceof Error ? e.message : e)} — emitting in-band truncation signal`);\n                emitUpstreamTruncation(res, \"commandcode\", finalFinishReason !== undefined, log);\n                return;\n            }\n            if (done) break;\n            buf += decoder.decode(value, { stream: true });\n            let idx: number;\n            while ((idx = buf.indexOf(\"\\n\")) >= 0) {\n                const line = buf.slice(0, idx);\n                buf = buf.slice(idx + 1);\n                if (line.trim().length === 0) continue;\n                let ev: Record<string, unknown>;\n                try {\n                    ev = JSON.parse(line) as Record<string, unknown>;\n                } catch {\n                    if (!res.write(Buffer.from(line + \"\\n\", \"utf8\"))) await awaitDrain(res);\n                    continue;\n                }\n                const type = ev[\"type\"];\n                let outLine = line;\n                if ((type === \"text-delta\" || type === \"reasoning-delta\") && typeof ev[\"text\"] === \"string\") {\n                    const f = type === \"text-delta\" ? textFilter : reasonFilter;\n                    const clean = f.push(ev[\"text\"] as string);\n                    if (type === \"text-delta\") visibleTextChars += clean.length;\n                    if (clean !== ev[\"text\"]) outLine = JSON.stringify({ ...ev, text: clean });\n                } else if (type === \"finish\") {\n                    await flushFieldTails();\n                    sawTerminal = true;\n                    if (typeof ev[\"finishReason\"] === \"string\") finalFinishReason = ev[\"finishReason\"] as string;\n                    const tu = ev[\"totalUsage\"];\n                    if (tu !== null && typeof tu === \"object\" && !Array.isArray(tu)) {\n                        const t = tu as Record<string, unknown>;\n                        if (typeof t[\"inputTokens\"] === \"number\") acc.inputTokens = t[\"inputTokens\"] as number;\n                        if (typeof t[\"outputTokens\"] === \"number\") acc.outputTokens = t[\"outputTokens\"] as number;\n                        const details = t[\"inputTokenDetails\"];\n                        if (details !== null && typeof details === \"object\" && typeof (details as Record<string, unknown>)[\"cacheReadTokens\"] === \"number\") {\n                            acc.cachedTokens = (details as Record<string, unknown>)[\"cacheReadTokens\"] as number;\n                        }\n                    }\n                } else if (type === \"error\") {\n                    sawTerminal = true;\n                    await flushFieldTails();\n                }\n                if (!res.write(Buffer.from(outLine + \"\\n\", \"utf8\"))) await awaitDrain(res);\n            }\n        }\n        await flushFieldTails();\n        if (buf.trim().length > 0 && !res.destroyed && !res.writableEnded) {\n            if (!res.write(Buffer.from(buf + \"\\n\", \"utf8\"))) await awaitDrain(res);\n        }\n        settleUsage();\n        maybeWarnDegenerate();\n    } catch (e) {\n        settleUsage();\n        if (res.destroyed || res.writableEnded) {\n            log?.(\"client aborted mid-stream\");\n            return;\n        }\n        try { await flushFieldTails(); } catch { /* client half-gone; the signal below is best-effort too */ }\n        loggerLog(\"warn\", `[plugin] upstream stream read failed (commandcode): ${String(e instanceof Error ? e.message : e)} — emitting in-band truncation signal`);\n        emitUpstreamTruncation(res, \"commandcode\", finalFinishReason !== undefined, log);\n        return;\n    } finally {\n        reader.releaseLock();\n        res.end();\n    }\n}\n\n/** #5951: name a read failure in the truncation diag. The socket's own code\n *  (`ECONNRESET`, `UND_ERR_SOCKET`, ...) is what tells a provider disconnect\n *  apart from a local abort, and it is the only part of the cause that is not\n *  already implied by `cause=\"read-error\"`. */\nfunction describeReadError(error: unknown): string {\n    if (!(error instanceof Error)) return String(error).replace(/[\\r\\n]+/g, \" \").slice(0, 200);\n    const code = (error as { code?: unknown }).code;\n    const name = typeof code === \"string\" && code.length > 0 ? `${error.name}/${code}` : error.name;\n    return `${name}: ${error.message}`.replace(/[\\r\\n]+/g, \" \").slice(0, 200);\n}\n\n/** Retain only bounded, structured cause identity; never serialize upstream text. */\nfunction describeReadErrorCause(error: unknown): Array<{ name: string; code?: string }> | undefined {\n    if (!(error instanceof Error)) return undefined;\n    const chain: Array<{ name: string; code?: string }> = [];\n    let cause: unknown = error.cause;\n    for (let depth = 0; depth < 3 && cause instanceof Error; depth++) {\n        const name = /^[A-Za-z][A-Za-z0-9_.-]{0,63}$/.test(cause.name) ? cause.name : \"Error\";\n        const codeValue = (cause as Error & { code?: unknown }).code;\n        const code = typeof codeValue === \"string\" && /^[A-Za-z0-9_]{1,64}$/.test(codeValue) ? codeValue : undefined;\n        chain.push({ name, ...(code ? { code } : {}) });\n        cause = cause.cause;\n    }\n    return chain.length > 0 ? chain : undefined;\n}\n\nfunction safeDiagnosticId(value: string | undefined): string | undefined {\n    return value !== undefined && value.length <= 128 && /^[A-Za-z0-9][A-Za-z0-9._:-]*$/.test(value) ? value : undefined;\n}\n\nfunction hadTextOtherThanTextFields(choices: unknown): boolean {\n    if (!Array.isArray(choices)) return true;\n    for (const c of choices) {\n        if (!c || typeof c !== \"object\") continue;\n        const ch = c as Record<string, unknown>;\n        // #2405: an empty finish_reason carries nothing the client needs.\n        if (typeof ch[\"finish_reason\"] === \"string\" && ch[\"finish_reason\"] !== \"\") return true;\n        const d = ch[\"delta\"] as Record<string, unknown> | undefined;\n        if (!d) continue;\n        for (const k of Object.keys(d)) {\n            if (k !== \"content\" && k !== \"reasoning_content\" && k !== \"reasoning\") return true;\n        }\n    }\n    return false;\n}\n\n// #2190: residue audit for frames forwarded verbatim by a raw exit — i.e. a\n// frame whose text lives OUTSIDE the managed fields (or is not parseable) and\n// therefore never touches the tag-echo state machine. Log-only: the bytes are\n// forwarded exactly as received (#1039 wire fidelity); the point is that such\n// a leak is observable in the log instead of silent.\nfunction auditRawForward(rawEvent: string): void {\n    if (containsEchoResidue(rawEvent)) {\n        loggerLog(\"warn\", `[tag-echo] raw forward carried echo-residue-shaped bytes (#2190): ${rawEvent.slice(0, 80).replace(/\\n/g, \" \")}`);\n    }\n}\n\n// #2190 companion to auditRawForward: tool-call argument fragments are user\n// intent (#1039) and may legitimately match the residue shape, so frames\n// carrying them are excluded from the audit.\nfunction openaiFrameHasToolCalls(choices: unknown): boolean {\n    if (!Array.isArray(choices)) return false;\n    for (const c of choices) {\n        const d = c && typeof c === \"object\" ? (c as Record<string, unknown>)[\"delta\"] : undefined;\n        // != null: sglang-style explicit \"tool_calls\": null deltas are not tool\n        // calls (see the sawToolUse fix above); they must not suppress the\n        // echo-residue audit either.\n        if (d && typeof d === \"object\" && (d as Record<string, unknown>)[\"tool_calls\"] != null) return true;\n    }\n    return false;\n}\n\n// #2248 companion to auditRawForward (responses wire): tool-call argument\n// streams (response.function_call_arguments.*, response.custom_tool_call_input.*)\n// fall through the unrecognized-type exit and are user intent (#1039) — exclude.\nfunction responsesFrameHasToolCalls(ev: Record<string, unknown>): boolean {\n    const t = ev[\"type\"];\n    if (typeof t === \"string\" && (t.includes(\"function_call\") || t.includes(\"custom_tool_call\"))) return true;\n    if (ev[\"arguments\"] !== undefined) return true;\n    const item = ev[\"item\"];\n    if (item && typeof item === \"object\") {\n        const it = (item as Record<string, unknown>)[\"type\"];\n        if (it === \"function_call\" || it === \"custom_tool_call\") return true;\n    }\n    return false;\n}\n\n/** The Gemini counterpart of hadTextOtherThanTextFields: does a frame whose\n *  text parts were all stripped still carry something the client needs? A\n *  finishReason, a functionCall/functionResponse part, usageMetadata or\n *  promptFeedback keeps the chunk alive; a chunk that only ever held\n *  render-tag echo is dropped whole. */\nfunction googleFrameHasNonText(ev: Record<string, unknown>): boolean {\n    if (ev[\"usageMetadata\"] !== undefined || ev[\"promptFeedback\"] !== undefined) return true;\n    const candidates = ev[\"candidates\"];\n    if (!Array.isArray(candidates)) return true;\n    for (const c of candidates) {\n        if (!c || typeof c !== \"object\") continue;\n        const cand = c as Record<string, unknown>;\n        // #2405: an empty finishReason carries nothing the client needs.\n        if (typeof cand[\"finishReason\"] === \"string\" && cand[\"finishReason\"] !== \"\") return true;\n        const content = cand[\"content\"];\n        const parts = content && typeof content === \"object\" ? (content as Record<string, unknown>)[\"parts\"] : undefined;\n        if (!Array.isArray(parts)) continue;\n        for (const p of parts) {\n            if (!p || typeof p !== \"object\") continue;\n            for (const k of Object.keys(p as Record<string, unknown>)) {\n                if (k !== \"text\" && k !== \"thought\" && k !== \"thoughtSignature\") return true;\n            }\n        }\n    }\n    return false;\n}\n\n/**\n * Plugin-mode Responses passthrough with render-tag stripping (#206 parity\n * for VERBATIM plugin streams). In plugin mode the native tool loop owns the\n * tool surface, so function_call events must reach the agent untouched — but\n * the model's *prose* can still echo ACP render tags (observed with omp/\n * qwen: tags flatten into standalone messages, get stamped with refs, replay,\n * and amplify). This pipe keeps every event byte-identical except\n * `response.output_text.delta`, whose delta text streams through the same\n * tag-echo state machine the compress loop uses. A held tail is flushed as a\n * final delta before the first done/completed event so the client's assembled\n * text never loses content.\n *\n *  Also serves proxy-mode Responses SSE that skipped compress injection\n *  (#460, e.g. ACP_NO_INJECT_TOOL). Pass no session there — see\n *  pipePluginChatWithStrip for why usage accounting must be skipped.\n *\n *  #732/#821 parity with pipePluginChatWithStrip: when the turn's completion\n *  reports a clean status with nothing visible — the echoed render tag was the\n *  only thing the model emitted, and the filter emptied it — the agent's own\n *  body is re-issued ONCE with a continuation nudge instead of leaving the host\n *  with an empty completed turn. The retry is reframed onto the ids the client\n *  already holds, so the client still sees one turn. */\nexport async function pipePluginResponsesWithStrip(\n    stream: ReadableStream<Uint8Array>,\n    res: ServerResponse,\n    session?: Session,\n    log?: (msg: string) => void,\n    refetch?: () => Promise<ReadableStream<Uint8Array> | null>,\n    upstreamOrigin?: string,\n    // See pipePluginChatWithStrip: whole-field tool-call emission drop,\n    // gated on the request carrying the [ACP absorb] instruction (m00885).\n    absorbInstructed?: boolean,\n    // m00885: echoed (user-requested verbatim) emission spans survive.\n    requestText?: string,\n    // #2328 Q2 — see pipePluginChatWithStrip.\n    upstreamMeta?: UpstreamMeta,\n    reply?: HandoffReply,\n    hostOwnsTruncationRecovery = false,\n): Promise<void> {\n    let reader = stream.getReader();\n    let decoder = new TextDecoder(\"utf-8\");\n    let buf = \"\";\n    const acc: UsageSample = {};\n    const replyItems = new Map<number, Record<string, unknown>>();\n    let replyBytes = 0;\n    let replyDropped = false;\n    const appendReplyDelta = (meta: Record<string, unknown>, text: string, reasoning = false) => {\n        if (!reply || replyDropped || !text) return;\n        const index = Number(meta[\"output_index\"] ?? 0);\n        const existing = replyItems.get(index);\n        replyBytes += Buffer.byteLength(text) + (existing ? 0 : 128);\n        if (replyBytes > HANDOFF_REPLY_MAX_BYTES) { replyDropped = true; replyItems.clear(); reply.discard(); return; }\n        const item = existing ?? (reasoning ? { type: \"reasoning\", summary: [] } : { type: \"message\", role: \"assistant\", content: [] });\n        const field = reasoning ? \"summary\" : \"content\";\n        const parts = (Array.isArray(item[field]) ? item[field] : []) as Array<{ type: string; text: string }>;\n        const at = Number(meta[reasoning ? \"summary_index\" : \"content_index\"] ?? 0);\n        if (!Number.isInteger(at) || at < 0 || at > 10000) { replyDropped = true; replyItems.clear(); reply.discard(); return; }\n        const part = parts[at] ?? { type: reasoning ? \"summary_text\" : \"output_text\", text: \"\" };\n        part.text += text;\n        parts[at] = part;\n        item[field] = parts;\n        replyItems.set(index, item);\n    };\n    let replyCompleted = false;\n    // #2328 Q2/Q4 — see the chat-pipe twin.\n    let diagEvents = 0;\n    let diag