e-level\n    // compress cascade (global → provider); default off = byte-for-byte passthrough.\n    // The kernel decides (turn kind / verbosity / lower-effort); bili only lands it.\n    // Resolved at provider granularity — verbosity/effort routing isn't model-specific\n    // and extracting a model across all four wires here is disproportionate.\n    const steerRaw = resolveCompress(opts.routes, upstreamUrl, undefined, opts.compress).outputSteering;\n    const steerResolved = steerRaw !== undefined ? resolveOutputSteeringConfig(steerRaw) : null;\n    const steerCfg = steerResolved?.config ?? null;\n    for (const w of steerResolved?.warnings ?? []) log(\"warn\", `[${prepared?.session.id ?? \"passthrough\"}] [output-steering] ${w}`);\n    let steerProtocol: WireProtocol | null = null;\n    // #564/#2627 final-wire provenance: the transformed object graph the bytes\n    // are (re)serialized from, and this turn's manifest re-anchored onto it.\n    // Everything below mutates ONE graph in place, so a marker carrier keeps its\n    // object identity across compat roles / steering / drops / the checkpoint —\n    // that identity is the only thing the manifest may re-index by.\n    let wireObj: Record<string, unknown> | null = null;\n    let separatorManifest = prepared?.separatorManifest;\n    // #564/#2627: IMPORTANT distinction. `separatorManifest === undefined` means\n    // \"no producer claims were ever minted\" (or they were proven dead) — the judge\n    // must still judge separators normally. This flag records a DIFFERENT state:\n    // a producer DID mint claims, then an opaque host rewrite invalidated the\n    // proof, so ownership of this send's separators is UNKNOWN. The judge then\n    // skips only its separator-ownership checks (I1/I2 for separators) for this\n    // send — it grants no exemption and every other integrity check still runs.\n    let separatorOwnershipUnknown = false;\n    // Opaque host rewrite: the producer DID mint claims, their proof is gone, and\n    // the bytes still contain separators we can no longer attribute. Dropping the\n    // manifest alone would tell the judge \"no producer claims exist\" and it would\n    // then report a genuine host separator as a client insertion; the flag keeps\n    // the distinction alive through to the judge.\n    const invalidateSeparatorOwnership = (): void => {\n        if (separatorManifest !== undefined) {\n            separatorOwnershipUnknown = true;\n            separatorManifest = undefined;\n        }\n    };\n    // The graph is parsed lazily, only when a step needs object access, and it is\n    // serialized lazily too: an unchanged fast path keeps the original string.\n    const wireGraph = (): Record<string, unknown> | null => {\n        if (wireObj !== null) return wireObj;\n        // Seed from prepare's own parsed graph whenever the bytes still match what\n        // it serialized: that object IS the graph the manifest's carriers live in\n        // (collectSeparatorManifest walked it), so identity survives. A fresh\n        // JSON.parse would mint new objects and no claim could ever re-anchor.\n        let parsed: unknown = null;\n        // Seed from prepare's OWN parsed graph only when the bytes are the ones it\n        // serialized AND the manifest still proves each carrier sits at its claimed\n        // index — identity without that proof would re-anchor a claim the producer\n        // never actually made.\n        const seedable = separatorManifest !== undefined\n            && typeof wireBody === \"string\"\n            && wireBody === prepared?.body\n            && separatorManifestAnchored(\n                separatorManifest,\n                (prepared?.parsedBody as { input?: unknown } | undefined)?.input as readonly unknown[] | undefined,\n                wireBody,\n            );\n        if (typeof wireBody === \"string\") {\n            if (seedable) {\n                parsed = prepared?.parsedBody;\n            } else {\n                try { parsed = JSON.parse(wireBody); } catch { parsed = null; }\n            }\n        }\n        wireObj = parsed && typeof parsed === \"object\" && !Array.isArray(parsed) ? (parsed as Record<string, unknown>) : null;\n        // A body that no longer matches the prepared bytes (or an unparseable one,\n        // or a manifest whose anchor proof failed) cannot carry proven lineage\n        // forward — ownership becomes UNKNOWN, not \"nobody owns this\", so the judge\n        // stops asserting separator findings.\n        if (!seedable) invalidateSeparatorOwnership();\n        return wireObj;\n    };\n    // Publish an in-place mutation of `wireGraph()` as the new body: exactly one\n    // serialization per rewrite, and the manifest is re-anchored against THAT\n    // string so the judge's byte-equality binding stays honest.\n    const commitGraph = (): void => {\n        if (wireObj === null) return;\n        const serialized = JSON.stringify(wireObj);\n        wireBody = serialized;\n        if (separatorManifest !== undefined) {\n            const input = wireObj.input;\n            if (!Array.isArray(input)) {\n                // The container the carriers lived in is gone entirely — we cannot\n                // say whether they were deleted deliberately or the graph was\n                // replaced under us, so ownership is UNKNOWN.\n                invalidateSeparatorOwnership();\n                return;\n            }\n            separatorManifest = reanchorSeparatorManifest(separatorManifest, input, serialized);\n        }\n    };\n    if (typeof body === \"string\") {\n        // upstreamUrl (the real destination) — not route?.rewrittenUrl, which\n        // is undefined for zero-config requests and would skip provider compat.\n        const configured = resolveCompatRoles(opts.routes, upstreamUrl, opts.compat?.roles);\n        // #552 learn-on-failure: roles this session learned from a role-\n        // rejection 400 overlay the configur